(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["audio"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-streamwise-multimodal-sched"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-1\">一 · 事故现场：一次被“统一批”拖垮的语音直播</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-2\">二 · 它到底解决什么：阶段异构性下的资源错配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-3\">三 · 不解决什么：三条它管不到的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-4\">四 · 为什么必须是“阶段 × 模态”而不是“请求”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-5\">五 · 失败模式的工程读法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-6\">六 · 适用性判据：什么时候不该拆池</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-7\">七 · 阶段解耦的失效面：跨池带宽、抢占抖动与帧块节拍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-8\">八 · 请求入队与阶段拆分：一次模态路由的代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-9\">九 · 预填池：批量条件编码与 KV 移交</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-10\">十 · 解码池：连续批处理与 token 预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-11\">十一 · 声码器池：帧块批处理与流水线并行</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-12\">十二 · SLO 监控、抢占与重排：尾延迟的闭环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-13\">十三 · 跨池迁移的带宽账与失败模式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-14\">十四 · SLO 可行域与利用率目标的联合形式化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-15\">十五 · 资源分配式的逐项拆解与拉格朗日一步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-16\">十六 · 首块时延的分解式与关键路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-17\">十七 · 连续批处理的 token 预算伪代码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-18\">十八 · 帧块节奏匹配与流水线气泡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-19\">十九 · 抢占判据与最小驻留时间的可实现形式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-20\">二十 · 阶段解耦调度的失效边界与跨池代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-21\">二十一 · 负载形态的判别：什么样的请求配方才喂得饱阶段解耦</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-22\">二十二 · 长度分布：重尾是配方的主要敌人</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-23\">二十三 · 并发与批大小：三个池的批不是同一个数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-24\">二十四 · 负载不对时的三种失效及其可观测信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-25\">二十五 · 配方的容量规划含义：按阶段计费与按池定容</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-26\">二十六 · 硬件档位：按池的算术强度分档，而非按整机分档</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-27\">二十七 · 并行拓扑：跨池流水线 + 池内张量并行，两层不要混</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-28\">二十八 · 量化方案：按池独立选格式，跨池边界保持数值契约</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-29\">二十九 · KV 策略：容量、迁移与驻留三件事分开配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-30\">三十 · 调度参数：把 SLO 约束翻译成四个旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-31\">三十一 · 一个可复现的配置流程</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-32\">三十二 · 跨池迁移：显存拷贝与同步的硬账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-33\">三十三 · 池间带宽竞争与流水线气泡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-34\">三十四 · 抢占与重排：抖动从哪里来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-35\">三十五 · 功耗与热：被忽略的第三约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-36\">三十六 · 规模上限：先崩的是哪一环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-37\">三十七 · 调度器的可观测性设计</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-38\">三十八 · 跨池流水线的代价拐点：带宽、显存与尾延迟震荡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-39\">三十九 · 精度问题：跨池迁移中的数值漂移与帧块错位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-40\">四十 · OOM：显存账本的三处漏算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-41\">四十一 · 批抖动与路由不均：抢占策略的两个反面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-42\">四十二 · 尾延迟尖刺：SLO 边界的震荡与诊断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-43\">四十三 · 监控面与回滚：按池的灰度与状态重放</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-44\">四十四 · 对照维度：把“同族”拆成四个可判定的轴</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-45\">四十五 · 决策表：五类同族算法的适用条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-46\">四十六 · 资源分配的判定式：alloc 与 SLO 可行性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-47\">四十七 · 抢占语义的选型：软抢占、冷却窗口与饥饿</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-48\">四十八 · 耦合方式对照：流水线、串行与模型内并行</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-49\">四十九 · 规模上限与退选条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streamwise-multimodal-sched-sec-50\">五十 · 阶段解耦调度的边界：何时该换回单池连续批处理</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:538px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 538.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"456.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求进入调度器，按模态与阶段拆分为预填任务、解码任务、声码器任务</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"456.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">预填池批量执行文本/音频条件编码，产出 KV cache 并移交解码池</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"456.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">解码池以连续批处理迭代自回归，按 token 预算动态增删请求</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"456.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">声码器池按帧块批处理波形合成，与解码池流水线并行</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"456.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">SLO 监控触发抢占与重排，尾延迟超限请求优先获得 SM 与带宽</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-streamwise-multimodal-sched-sec-1\">一 · 事故现场：一次被“统一批”拖垮的语音直播</h3>\n<p>某语音直播转写与合成一体的服务，白天把 ASR 与 TTS 两条链路塞进同一个连续批处理池：调度器按固定时间窗收批，把预填请求、自回归解码请求、声码器合成请求混在一张 batch 里，按最大序列长度对齐。事故发生在一次突发流量上——主播端突然出现大量短语音请求，预填任务瞬间把池内显存占满，KV cache 分页被挤压，正在迭代的自回归解码请求被迫等待；等到预填批次释放，解码请求已经积压成一条长尾，声码器拿不到帧块，波形输出断流。用户侧感知是“字幕延迟数秒、合成声音卡顿”，而 GPU 侧的 SM 利用率却在预填与解码交替的空档里掉到低位。这不是单点故障，而是统一批调度把三种计算特征完全不同的阶段强行耦合后的必然结果：预填是计算密集的大矩阵乘，解码是访存密集的逐 token 迭代，声码器是固定帧率的波形合成，三者的最优批大小、显存占用曲线与尾延迟分布根本不在同一个尺度上。</p>\n<p>这个事故暴露的核心矛盾可以用一个约束式写清楚：服务要满足的是分阶段的尾延迟目标，而不是平均吞吐。设第 $j$ 个阶段（预填、解码、声码器）的尾延迟为 $L_j$、服务目标为 $\\text{SLO}_j$，则可用性条件为</p>\n<div class=\"formula\">$$\\text{SLO}_{\\text{ok}} = \\Pr\\big(L_{\\text{first}} \\le L^{\\star}\\big) \\ge 1-\\epsilon,\\quad \\text{util}=\\frac{\\sum \\text{SM}_{\\text{busy}}}{\\text{SM}_{\\text{total}}}$$</div>\n<p>统一批调度优化的是 $\\text{util}$ 的瞬时值，却无法保证 $\\Pr(L_{\\text{first}} \\le L^{\\star})$——首包延迟被预填批次的长尾直接拉高，而 $\\epsilon$ 一旦被突破，实时语音场景就没有补救余地。事故的工程教训是：多模态流式服务的调度单位必须是“阶段 × 模态”，而不是“请求”。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-2\">二 · 它到底解决什么：阶段异构性下的资源错配</h3>\n<p>多模态生成服务（语音、文本、视频混合流式）的请求在时间轴上会依次穿过三类计算形态迥异的阶段。预填阶段批量执行文本与音频条件编码，产出 KV cache，其计算特征是大的 GEMM、显存带宽压力集中在权重读取；解码阶段以连续批处理迭代自回归，逐 token 产出，特征是 KV cache 读写密集、批内序列长度高度不均；声码器/解码器阶段按帧块合成波形或视频帧，特征是固定节奏、对帧块到达的时序敏感。统一批调度把这三段压进一个池，等于用同一套批大小与抢占策略去服务三种截然不同的负载，结果是预填阻塞解码、解码拖累声码器，SM 在阶段切换时反复空转。</p>\n<p>本算法解决的就是这个资源错配：按阶段拆分资源池，以 token/帧块为调度单位做连续批处理与抢占，按 SLO 分配 SM 与显存。其分配目标可写为</p>\n<div class=\"formula\">$$\\text{alloc}_j = \\arg\\max \\sum_j U_j \\;\\text{s.t.}\\; L_j \\le \\text{SLO}_j$$</div>\n<p>其中 $U_j$ 为第 $j$ 个池的 GPU 利用率，$L_j$ 为该池尾延迟，约束是每个阶段的尾延迟都不超限。注意这个目标函数与统一批调度的差别：它不是最大化全局平均利用率，而是在每个阶段的 SLO 约束下分别最大化该池利用率——预填池可以跑大 batch 吃满计算单元，解码池按 token 预算动态增删请求维持低尾延迟，声码器池按帧块节奏稳定输出。三者互不阻塞，预填与解码不再共享同一条显存与 SM 队列。</p>\n<p>适用边界由此清晰：它适合阶段计算特征差异大、且各阶段有独立尾延迟约束的多模态生成服务。它不解决单阶段内部的算子效率问题（那是 tcgen05、NVFP4、TMEM 与 2-SM MMA 的范畴，见算子与数值精度部分），也不解决跨节点集合通信的拓扑优化（那是 NVLink 5 与 NCCL/NIXL 的主题）。它更不适用于请求形态单一、阶段特征趋同的纯文本批推理——那种场景下拆池只会增加跨池迁移开销而无收益。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-3\">三 · 不解决什么：三条它管不到的边界</h3>\n<p>第一条边界是单请求内部的模型结构优化。阶段拆分不改变单个解码步的计算图，也不改变声码器的算子融合方式；如果解码池里单个 token 的生成因为权重布局或精度格式而低效，拆池无法补救。第二条边界是跨池数据搬运的物理上限。跨池 KV cache 与状态迁移要经过显存拷贝与同步，其代价与池间带宽成反比；当池间带宽不足时，流水线出现气泡，GPU 利用率反而下降——这正是失败模式之一，拆池的收益被迁移开销吃掉。第三条边界是抢占策略本身不产生计算资源，它只做重分配；如果总 SM 与显存不足以同时满足各池的 SLO 约束，约束式 $\\text{alloc}_j$ 无可行解，此时需要的是容量规划而非调度技巧。</p>\n<p>用一个具体例子说明第三条边界：假设解码池的 token 预算被设得过紧，尾延迟超限请求触发抢占，把预填池的 SM 抢走；预填池批次被切断后 KV cache 产出变慢，解码池又因缺少新请求而饥饿，形成“抢占—饥饿—再抢占”的循环，尾延迟在 SLO 边界反复震荡。这不是算法失效，而是配置越过了可行域。因此本算法必须配合最小驻留时间与重排冷却窗口，否则抢占与重排的复杂度会反噬稳定性。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-4\">四 · 为什么必须是“阶段 × 模态”而不是“请求”</h3>\n<p>把调度单位从请求下沉到 token/帧块，带来两个直接后果。其一是容量规划可计算：每个池的 SM 需求可以按其批内 token 数或帧块数与单位计算量估算，而不是按请求数拍脑袋。其二是计费与 SLO 可以按阶段归因：首包延迟由预填池决定，token 间延迟由解码池决定，波形连续性由声码器池决定，三者分别监控、分别扩容。这与统一批调度下“一个请求一个延迟数字”的黑盒形成对比。</p>\n<p>与相邻方案的差别也在这里划清：相比统一批调度（单池连续批处理），阶段解耦让预填与解码不再互相阻塞；相比单模型内多 token 预测的流式方案（如 FlashTTS 的 MTP 路线），本算法以跨模态阶段拆分为核心，而不是在单个模型内部做投机式多 token 预测。前者优化的是单步解码的 token 产出率，后者优化的是多阶段资源在时间轴上的重叠方式，两者可以叠加但不可互相替代。这也解释了为什么本算法在语音+文本+视频混合流式请求下才有明显收益：模态越多、阶段特征越分散，统一批的错配越严重。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-5\">五 · 失败模式的工程读法</h3>\n<p>三类失败模式对应三个可观测信号。跨池迁移开销导致的气泡，表现为池间拷贝带宽打满而各池 SM 利用率同时下滑；此时应检查 KV cache 迁移量是否超过池间带宽预算，而不是继续加大批大小。抢占配置不当导致的解码池饥饿或抖动，表现为尾延迟在 SLO 边界的高频振荡与抢占次数的异常上升；此时应引入最小驻留时间与重排冷却窗口，把抢占频率压到与 SLO 松弛度匹配的水平。声码器帧块节奏与解码 token 产出不匹配，表现为声码器池空转或积压；此时应按帧块到达速率反推解码池的 token 预算，而不是让两个池各自按最大吞吐跑。</p>\n<p>这三个信号的共同点是：它们都不是计算能力不足，而是池间耦合参数失配。工程判断应落在“先定 SLO 约束、再定池间带宽与迁移预算、最后调抢占参数”的顺序上；反过来先调批大小再补 SLO，就会重演第一节的事故。规模上限受跨池带宽与显存容量约束，材料未给出具体上限，因此在容量规划时应把跨池迁移量作为一等约束纳入模型，而不是当作事后优化项。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-6\">六 · 适用性判据：什么时候不该拆池</h3>\n<p>给出一个可操作的判据：若各阶段的最优批大小差异不足一个数量级、且阶段间尾延迟目标相近，拆池带来的迁移开销会超过解耦收益，应保持单池连续批处理；若阶段间计算特征差异显著（例如预填的 GEMM 主导与解码的 KV 访存主导并存）、且首包延迟与 token 间延迟分属不同 SLO 档位，则拆池是必要结构。判据的量化形式可以写成迁移开销与解耦收益的比值：当跨池 KV 拷贝与同步时间占该请求端到端延迟的比例超过解耦所换取的尾延迟改善比例时，拆池不成立。这个比值需要在真实负载下测量，材料未给出具体阈值，因此应以线上 SLO 监控数据为准做逐池校准，而不是套用固定参数。</p>\n<p>最终落在具体机制上：调度器入口按模态与阶段把请求拆成预填任务、解码任务、声码器任务，预填池批量产出 KV cache 并移交解码池，解码池以连续批处理按 token 预算动态增删请求，声码器池按帧块批处理并与解码池流水线并行；SLO 监控在尾延迟超限时触发抢占与重排，但必须受最小驻留时间与冷却窗口约束。这条链路的每一环都以“阶段 × 模态”为调度单位，而不是以请求为单位——这正是它与统一批调度、与单模型多 token 预测方案的分水岭。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-7\">七 · 阶段解耦的失效面：跨池带宽、抢占抖动与帧块节拍</h3>\n<p>阶段解耦并非免费午餐。它把一条原本在单池内闭合的数据流切成三段，代价是三段之间必须搬运状态：预填池产出的 KV cache 要移交解码池，解码池产出的隐变量要交给声码器池按帧块合成。这条跨池路径一旦带宽不足，流水线立刻出现气泡——预填池已完成、解码池却在等 KV 拷贝落地，声码器池则因帧块迟迟不到而空转。此时 GPU 利用率不升反降，因为三段池各自都在等上游，而不是在算。判断边界的第一条硬约束是：跨池迁移的数据量乘以请求速率，必须显著低于池间可用带宽，否则解耦收益被拷贝开销吃掉。用公式表达即调度器真正求解的是带尾延迟约束的利用率最大化：</p>\n<div class=\"formula\">$$\\text{alloc}_j = \\arg\\max \\sum_j U_j \\;\\text{s.t.}\\; L_j \\le \\text{SLO}_j$$</div>\n<p>该式看似温和，实则把两个失效条件写在了约束里。其一，$L_j$ 是各池尾延迟，而尾延迟对抢占极其敏感：SLO 监控触发重排时，若没有最小驻留时间与重排冷却窗口，被抢占的请求会在解码池与预填池之间来回迁移，尾延迟在 SLO 边界反复震荡，表现为解码池饥饿——新请求不断插入、老请求反复让位，解码池的有效批大小被压到很低，自回归迭代的 token 产出速率崩塌。其二，声码器池按帧块批处理，其到达节奏由解码池的 token 产出节拍决定；两者节拍不匹配时，声码器池要么积压帧块导致显存膨胀，要么长期空转拉低整体 $\\text{util}$。这不是参数调优能消除的，而是阶段计算特征差异的固有投影。</p>\n<p>因此本方案不解决的问题必须说清楚：它不解决单模态内部的批调度效率问题——若服务只有文本、阶段特征同质，拆池只会增加迁移开销而无收益；它不解决跨池带宽本身不足的硬件瓶颈，带宽受限时正确做法是退回统一批调度或缩小拆分粒度；它也不解决声码器与解码器节拍失配的结构性抖动，只能靠帧块预算与驻留策略缓解。一个具体的工程判断是：当某模态请求占比极高、其余模态仅为长尾时，为其单独建池会让该池长期低载而其他池被挤压，此时应按模态混合比动态调整池的 SM 配额，而非固定切分。规模上限由此被跨池带宽与显存容量共同锁定，超出后解耦的边际收益转负。</p>\n<h3 id=\"alg-streamwise-multimodal-sched-sec-8\">八 · 请求入队与阶段拆分：一次模态路由的代价</h3>\n<p>调度器的第一个动作不是批处理，而是把一个混合模态请求切成三类可独立排队的任务单元：预填任务（文本 token 序列、音频条件帧、视频条件帧）、解码任务（自回归 token 迭代）、声码器任务（波形帧块合成）。这一步的输入是请求描述符——模态组合、目标时长、首包延迟预算、流式分块粒度；输出是三张任务队列上的条目，每条带模态标签、阶段标签、SLO 约束与预估资源需求。代价不在算力，而在调度器本身的串行化：每个请求都要做一次模态判定与预算分摊，若调度器单线程处理入队，高并发下入队延迟会直接吃掉首包预算。</p>\n<p>拆分的关键判断是“哪些工作必须共享同一份条件编码”。文本条件与音频条件若在同一预填任务里编码，产出的 KV cache 可被解码池直接复用；若拆成两个预填任务，则解码池要做一次跨任务的 KV 拼接，多一次显存拷贝。因此拆分粒度应按“KV 复用边界”而非按模态机械切分。工程上把拆分逻辑写成纯函数，输入请求描述符、输出任务 DAG，便于在调度器热路径之外预计算。</p>\n<div class=\"formula\">$$\\text{alloc}_j = \\arg\\max \\sum_j U_j \\;\\text{s.t.}\\; L_j \\le \\text{SLO}_j$$</div>\n<p>这条分配式在入队阶段就已被“预占”：每个任务条目携带它所属池的 SLO 约束 $L_j \\le \\text{SLO}_j$，调度器据此决定该请求能否被接纳。若某池当前尾延迟已逼近 SLO，新请求要么被降级到低优先级队列，要么被拒绝——这是容量规划在请求粒度上的第一次体现。例子：一个语音+文本混合请求，文本预填只需数百 token，音频条件帧却是长序列，两者若同池批处理，文本任务会被音频任务的长预填拖住；拆开后文本预填池可先行完成并触发首 token 解码，首包延迟由文本侧决定。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-9\">九 · 预填池：批量条件编码与 KV 移交</h3>\n<p>预填池的输入是预填任务队列，输出是 KV cache 块句柄与一份“解码就绪”信号。执行方式是批量条件编码：把同模态、同序列长度档的任务聚成一批，走一次前向，产出每层的 K/V 张量并写入分页显存池。这里的具体机制是分页 KV 分配——预填不按请求连续分配显存，而是按块分配，块句柄随任务移交解码池，解码池按需追加新块。代价集中在两点：预填是计算密集型，批越大 SM 利用率越高，但批内最长序列决定整批的完成时间，长序列会拉高批尾延迟；KV 写入是带宽密集型，块分配与句柄登记带来额外的元数据开销。</p>\n<p>KV 移交是跨池的第一笔显存拷贝。若预填池与解码池在同一 GPU 上，移交只是句柄传递，零拷贝；若分处不同 GPU，则要走 NVLink 做块级传输，传输量与 KV 块大小成正比。工程判断：把预填池与解码池放在同一 NVLink 域内，让移交退化为句柄传递，是避免流水线气泡的首要配置。例子：音频条件编码产出的 KV 块若需跨节点搬运，单请求的 KV 传输会占用可观的链路带宽，在批内多请求并发移交时，链路成为预填池的隐性瓶颈，表现为预填池完成时间被拉长而非算力不足。</p>\n<p>预填池的吞吐指标应看“每 SM 每秒产出的 KV 块数”，而非单纯的 token 吞吐——因为下游解码池消费的是块，不是 token。容量规划时按块产出速率匹配解码池的块消费速率，两者失衡即出现池间积压或空转。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-10\">十 · 解码池：连续批处理与 token 预算</h3>\n<p>解码池的输入是预填池移交的 KV 块句柄与解码任务队列，输出是逐 token 的隐状态流与“可交付声码器”的帧块边界信号。具体机制是连续批处理：每个迭代步从活跃请求集合中按 token 预算挑选若干请求组成批，执行一次自回归前向，产出下一 token 并追加 KV 块；完成的请求退出批，新就绪请求插入批。token 预算的分配直接决定尾延迟——预算给足，批内请求多、吞吐高，但单请求的迭代间隔变长；预算收紧，尾延迟下降但 SM 利用率下滑。</p>\n<p>动态增删请求的判据是每个请求的剩余生成长度与已等待时长。工程上给每个请求维护一个“紧迫度”标量，紧迫度高的请求在预算分配时优先获得迭代机会。代价是调度决策本身的开销：每步都要重排活跃集合，若活跃请求数达到数百，重排的比较与排序开销会侵占解码前向的时间预算。缓解办法是把重排做成增量式——只在请求完成或新请求插入时更新有序结构，而非每步全量排序。</p>\n<p>解码池的显存代价随活跃请求数线性增长，因为每个活跃请求都持有自己的 KV 块链。分页分配让块可按需追加，但块碎片化会降低有效显存利用率；块大小选得过大，短请求浪费显存，块大小过小，块表元数据膨胀。这是解码池容量规划的核心权衡，需按请求长度分布定块大小，而非取固定值。例子：文本解码与语音解码若同池，语音请求的 KV 增长节奏与文本不同，混批会让批内迭代步的有效算力被长 KV 请求稀释，因此按模态分池或按 KV 长度档分桶是必要的。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-11\">十一 · 声码器池：帧块批处理与流水线并行</h3>\n<p>声码器池的输入是解码池产出的帧块边界信号与对应的隐状态块，输出是波形帧块。具体机制是按帧块批处理：把到达的帧块按固定帧数聚批，走一次波形合成前向，产出音频块并推给下游流式传输。它与解码池的并行方式是流水线——解码池产出第 $n$ 个帧块的隐状态时，声码器池正在合成第 $n-1$ 个帧块，两者在时间上重叠。</p>\n<p>流水线并行的代价是节奏匹配。解码 token 产出速率与帧块到达节奏若不一致，声码器池要么空转（帧块来得太慢，批凑不满），要么积压（帧块来得太快，批超出合成能力）。空转浪费 SM，积压拉高音频尾延迟。工程上给声码器池设一个帧块缓冲窗口，窗口深度按解码池的 token 产出抖动设定；窗口满则对解码池施加反压，窗口空则声码器池降低批大小以缩短单批合成时间。这是跨池反压的唯一通道，也是流水线稳定性的关键。</p>\n<p>声码器池的算力特征与解码池截然不同：它是短序列、高并行的卷积或转置卷积密集计算，批大小对吞吐的边际收益远高于解码池。因此声码器池的 SM 配额应偏向“大批少卡”，而解码池偏向“小批多卡”。按阶段拆分资源池的意义正在于此——统一批调度无法同时满足两种批大小偏好。例子：视频生成请求的帧块合成与音频帧块合成若共用声码器池，两者的帧率与块大小不同，混批会让批内计算图不一致，需按模态再分子池。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-12\">十二 · SLO 监控、抢占与重排：尾延迟的闭环</h3>\n<p>监控层的输入是各池的完成时间戳与队列深度，输出是抢占指令与重排信号。具体机制是尾延迟追踪：对每个池维护一个滑动窗口的分位数估计，当某池的尾延迟逼近其 SLO 约束时，触发抢占——从低优先级请求手中回收 SM 与带宽配额，转给尾延迟超限的请求。抢占的代价是状态迁移：被抢占的解码请求需保存其 KV 块链与迭代位置，挂起后重新入队；恢复时要重新加载 KV 块，这笔显存拷贝与同步开销直接计入该请求的总延迟。</p>\n<p>重排策略需设置最小驻留时间与重排冷却窗口。最小驻留时间防止请求刚被调度又被立刻抢占，造成抖动；冷却窗口防止同一请求在短时间内反复经历抢占-恢复循环。这两个参数配置不当的后果是解码池饥饿——高优先级请求持续抢占，低优先级请求永远得不到迭代机会；或尾延迟在 SLO 边界反复震荡——抢占触发后延迟短暂下降，恢复后立刻反弹。工程判断：抢占阈值应设在 SLO 约束的某个安全裕度之下，而非贴着 SLO 边界，给重排留出收敛空间。</p>\n<div class=\"formula\">$$\\text{SLO}_{\\text{ok}} = \\Pr\\big(L_{\\text{first}} \\le L^{\\star}\\big) \\ge 1-\\epsilon,\\quad \\text{util}=\\frac{\\sum \\text{SM}_{\\text{busy}}}{\\text{SM}_{\\text{total}}}$$</div>\n<p>首包延迟 $L_{\\text{first}}$ 的达标概率是跨池指标，它由预填池完成时间、KV 移交时间、解码池首次迭代时间三者叠加决定。任何一池的尾延迟恶化都会拉低这个概率。因此监控不能只看单池分位数，要看端到端首包延迟的分布，并把超限请求的归因拆到具体池。例子：首包延迟超限的请求若归因于 KV 移交，则扩容 NVLink 带宽或调整池放置；若归因于解码池首次迭代排队，则调整 token 预算或抢占阈值。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-13\">十三 · 跨池迁移的带宽账与失败模式</h3>\n<p>跨池 KV 与状态迁移的代价必须按带宽记账。预填到解码的 KV 移交量等于块数乘块大小；解码到声码器的隐状态块移交量等于帧块数乘隐状态维度。这两笔传输若与计算重叠不足，流水线出现气泡，GPU 利用率反而低于统一批调度——这是阶段解耦的典型失败模式。工程上把迁移做成异步：移交发起后立即返回句柄，接收池在需要消费时才等待完成事件，用计算掩盖传输。</p>\n<p>第二个失败模式是声码器池与解码池的节奏失配，前文已述反压机制。第三个失败模式是抢占配置不当导致的解码池饥饿与尾延迟震荡。三者共同指向一个判断：阶段解耦的收益来自各池按自身计算特征批处理，但收益能否兑现取决于跨池带宽是否充足、反压通道是否通畅、抢占参数是否留有裕度。容量规划时应先按跨池带宽定规模上限，再按各池 SLO 分配 SM 与显存——顺序颠倒会导致池拆分后总算力够、端到端却跑不满。</p>\n<p>按 token/帧块为调度单位的另一个工程价值是可计费性：每个请求消耗的 token 预算与帧块配额可精确归集到池，使按 SLO 计费成为可能。这要求调度器在任务条目上记录资源消耗的原子计数，而非事后按请求时长估算。例子：一个长语音请求在解码池消耗的迭代步数与在声码器池消耗的帧块批次数可分别记账，两者相加即该请求的跨池资源账单，为容量规划提供按阶段的真实消耗分布。</p>\n<h3 id=\"alg-streamwise-multimodal-sched-sec-14\">十四 · SLO 可行域与利用率目标的联合形式化</h3>\n<p>阶段解耦调度的第一件事，是把\"服务目标\"写成可判定的约束，而不是一句模糊的\"要快\"。给定一条多模态流式请求，其端到端体验由首块时延决定：用户听到第一段音频或看到第一帧画面之前的所有排队、预填、首批解码与首帧合成都计入 <span>L_first</span>。于是可行性判据是概率形式的：</p>\n<div class=\"formula\">$$\\text{SLO}_{\\text{ok}} = \\Pr\\big(L_{\\text{first}} \\le L^{\\star}\\big) \\ge 1-\\epsilon,\\quad \\text{util}=\\frac{\\sum \\text{SM}_{\\text{busy}}}{\\text{SM}_{\\text{total}}}$$</div>\n<p>逐项解释：<span>L_first</span> 是随机变量而非定值，因为它取决于到达时刻的批内竞争、抢占次数、跨池迁移耗时；<span>L*</span> 是业务给定的首块时延上限；<span>ε</span> 是允许的超限概率，通常远小于 1，代表\"尾\"的容忍度。右式的 <span>util</span> 是 SM 时间片占用率，分子按每个池实际占用 SM 的时长累加，分母是资源池可分配的 SM 总量。两个式子必须同时看：只追 <span>util</span> 会把长请求堆在一个池里拖垮尾延迟，只追 <span>L*</span> 则会让 SM 大量空转。</p>\n<p>推导的关键一步在于把概率约束转成确定性约束。对 <span>L_first</span> 做分位数近似：若我们把调度决策建立在\"当前批的预测完成时间\"上，则要求预测值不超过 <span>L*</span> 的分位点，即用 <span>L_first</span> 的经验分布 <span>F</span> 取 <span>F^{-1}(1-ε)</span> 作为硬阈值。工程上等价于：调度器维护每个池的尾延迟滑动分位数，任何新请求入池前先检查\"加入后该池分位数是否越界\"，越界则拒绝入池或触发抢占。这一步把随机约束降级为每次决策的布尔判断，才可能落到代码里。</p>\n<p>代价方面：分位数估计本身需要采样窗口，窗口太短会抖动、太长会迟钝；而每次入池检查都要读一次池状态，属于调度器热路径上的固定开销。具体例子：一个语音+文本混合请求，文本预填在预填池占用的 SM 时间片与音频条件编码共享同一批，若预填池分位数已逼近阈值，则该请求被推后一个调度周期入池，代价是首块时延增加一个周期，换来的是整池尾延迟不越界。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-15\">十五 · 资源分配式的逐项拆解与拉格朗日一步</h3>\n<p>核心分配式写成：</p>\n<div class=\"formula\">$$\\text{alloc}_j = \\arg\\max \\sum_j U_j \\;\\text{s.t.}\\; L_j \\le \\text{SLO}_j$$</div>\n<p>这里 <span>j</span> 遍历池（预填池、解码池、声码器池），<span>U_j</span> 是第 <span>j</span> 池的 GPU 利用率，<span>L_j</span> 是该池尾延迟，<span>SLO_j</span> 是该阶段的服务目标。注意约束是逐池的而非全局的：解码池的尾延迟不能靠预填池的空转来补偿，因为跨池流水线让下游池的输入节奏由上游池决定，单池越界会沿数据流放大。</p>\n<p>推导的关键一步是引入拉格朗日乘子把约束并入目标。构造 <span>𝓛 = Σ_j U_j − Σ_j λ_j (L_j − SLO_j)</span>，对 <span>U_j</span> 求偏导得到最优性条件：只有当\"提高该池利用率所带来的边际收益\"等于\"λ_j 乘以该池尾延迟对利用率的边际敏感度\"时，分配才停止调整。物理含义很直接：<span>λ_j</span> 大的池，说明它的尾延迟约束是紧的，调度器应当少给它塞请求、多留 SM 余量；<span>λ_j</span> 接近零的池则可以继续加压。工程上不必真的解优化，只需用 <span>λ_j</span> 作为\"该池还能不能再吃请求\"的软信号——尾延迟分位数越接近阈值，<span>λ_j</span> 越大，入池门槛越高。</p>\n<p>代价：<span>λ_j</span> 的在线估计需要每池独立的反馈回路，且乘子随负载漂移，更新过慢会导致分配滞后于到达率变化，更新过快则引起池间来回搬运请求的振荡。具体例子：声码器池按帧块批处理，若其 <span>λ</span> 升高说明帧块积压，调度器应减少向解码池增发 token 预算，让解码节奏与合成节奏对齐，而不是继续给解码池加 SM——后者只会把积压从声码器池搬到更下游。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-16\">十六 · 首块时延的分解式与关键路径</h3>\n<p>要把 <span>L_first</span> 落到可计算，需按数据流拆成四段之和：</p>\n<div class=\"formula\">$$L_{\\text{first}} = T_{\\text{queue}} + T_{\\text{prefill}} + T_{\\text{decode}}^{(1)} + T_{\\text{voc}}^{(1)} + T_{\\text{mig}}$$</div>\n<p>各项含义：<span>T_queue</span> 是请求在调度器等待入池的时间；<span>T_prefill</span> 是预填池批量执行条件编码并产出 KV cache 的时间；<span>T_decode^(1)</span> 是解码池产出首批 token 的迭代时间；<span>T_voc^(1)</span> 是声码器池合成首帧波形的时间；<span>T_mig</span> 是跨池 KV cache 与状态迁移的拷贝与同步开销。推导的关键一步是识别关键路径：在流水线并行下，<span>T_prefill</span> 与 <span>T_voc^(1)</span> 可以与其他请求的段重叠，但 <span>T_mig</span> 是串行插入的，它不与其他段重叠，因此是首块时延里最\"硬\"的一项。</p>\n<p>这解释了为什么跨池迁移的显存拷贝是这套机制的结构性代价：迁移走的是池间带宽，若带宽不足，<span>T_mig</span> 会显著抬高 <span>L_first</span> 的分布尾部，而尾部正是 <span>Pr(L_first ≤ L*)</span> 最敏感的部分。工程判断：迁移应尽量做零拷贝的句柄传递（KV cache 块地址与元数据移交），只在池间显存不共享时才真正拷贝；同时把迁移与下一请求的预填重叠，用预填的计算时间掩盖拷贝时间。</p>\n<p>具体例子：一条视频+语音请求，预填池完成视觉条件编码后需把 KV 移交解码池，若两块显存分属不同 GPU，迁移是一次跨卡拷贝；调度器可把该拷贝排在下一条请求预填的同一时间窗内，使 <span>T_mig</span> 不落在关键路径上。代价是调度器需维护迁移队列与预填队列的配对关系，配置不当会让迁移等待预填，反而拉长首块时延。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-17\">十七 · 连续批处理的 token 预算伪代码</h3>\n<p>解码池的核心循环是连续批处理：每轮迭代从活跃请求集合中按 token 预算挑选，执行一步自回归，产出的 token 推给声码器池。伪代码思路如下（以文字描述代替代码块）：维护活跃集 <span>A</span>；每轮计算剩余预算 <span>B</span>；按优先级排序 <span>A</span>，优先级由\"距 SLO 阈值的余量\"决定，余量小的排前；依次取请求，若其本步所需 token 数不超过 <span>B</span> 则加入本轮批，扣减 <span>B</span>；执行一步前向，写回 KV，把新 token 入帧块队列；若某请求完成或超时则移出 <span>A</span>；若 <span>B</span> 耗尽仍有请求未入选，记录饥饿计数，连续多轮未入选则触发抢占。</p>\n<p>推导的关键一步是把\"动态增删请求\"写成预算约束下的贪心：每轮批的大小不是固定值，而是由 <span>B</span> 与各请求的单步开销共同决定，因此批内请求数随负载浮动。这带来一个必须处理的副作用——贪心按优先级排序会让低优先级请求长期得不到预算，即解码池饥饿。稳定性技巧是给每个请求设最小驻留时间与重排冷却窗口：被抢占的请求在冷却窗口内不得再次被抢占，避免同一请求在 SLO 边界反复进出造成抖动。</p>\n<p>代价：每轮排序与预算检查是调度器热路径开销，活跃集越大开销越高；而抢占意味着丢弃已算出的部分 KV 或将其暂存，前者损失计算、后者占用显存。具体例子：解码池活跃集含若干语音与文本请求，某语音请求因首块时延余量最小被排到最前，连续两轮获得预算后完成首块；若它连续三轮未入选，饥饿计数触发抢占，把 SM 从其后的低优先级请求转移给它，代价是被抢占请求的 KV 需暂存，占用一段显存直到冷却窗口结束。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-18\">十八 · 帧块节奏匹配与流水线气泡</h3>\n<p>声码器池按帧块批处理，其输入节奏由解码池的 token 产出速率决定。设解码池每轮产出 <span>r</span> 个 token、每 <span>k</span> 个 token 组成一个帧块，则帧块到达速率为 <span>r/k</span>；声码器池单批处理 <span>m</span> 个帧块、每批耗时 <span>t_v</span>，则其吞吐为 <span>m/t_v</span>。流水线不出现气泡的条件是两者匹配：</p>\n<div class=\"formula\">$$\\frac{r}{k} \\le \\frac{m}{t_v}$$</div>\n<p>推导的关键一步是把\"节奏不匹配\"量化为速率不等式：左侧是上游供给，右侧是下游消化能力。若左侧大于右侧，帧块在声码器池积压，池内排队增长，尾延迟上升；若左侧小于右侧，声码器池空转，SM 利用率下降——这正是失败模式中\"声码器池空转或积压\"的定量来源。调度器的应对不是简单调 <span>m</span>，而是通过 token 预算间接调 <span>r</span>：当声码器池积压时收紧解码池预算，当声码器池空转时放宽预算并允许解码池多算几步。</p>\n<p>代价：调 <span>r</span> 会影响解码池自身的批效率，预算收紧意味着批变小、SM 利用率下降；而调 <span>m</span> 受声码器池显存限制，帧块批越大波形缓冲占用越多。具体例子：一条长语音请求解码产出快于合成，帧块积压使声码器池尾延迟逼近阈值，调度器收紧解码预算并把腾出的 SM 分给声码器池扩大 <span>m</span>，代价是解码池批变小、其利用率短暂下降，但整条流水线的首块时延分布尾部收窄。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-19\">十九 · 抢占判据与最小驻留时间的可实现形式</h3>\n<p>抢占不能凭\"感觉尾延迟高了\"就触发，需写成可判定的判据。设请求 <span>i</span> 的预测首块时延为 <span>L̂_i</span>，其所属池的尾延迟分位数为 <span>Q_j</span>，阈值为 <span>SLO_j</span>。触发条件为：<span>L̂_i > L*</span> 且 <span>Q_j > SLO_j</span> 同时成立，即\"该请求自身要超限\"且\"池整体已在越界边缘\"。只满足前者时优先做池内重排（把它提前），只满足后者时优先做池间资源再分配（给该池加 SM），两者同时满足才执行跨请求抢占。</p>\n<p>推导的关键一步是把抢占的收益写成\"被抢占请求的时延增量\"与\"受益请求的时延减量\"之差：只有当减量大于增量时才值得抢占，否则只是把尾延迟从一个请求搬到另一个请求。工程上用一个简单代理：受益请求的余量越小、被抢占请求的余量越大，抢占越划算。配合最小驻留时间——请求入池后至少驻留若干个调度周期才可被抢占——可以避免刚入池就被踢出的抖动。</p>\n<p>代价：抢占涉及 KV 暂存与状态恢复，是显存与带宽的双重开销；重排冷却窗口则限制了调度器的反应速度，窗口过长会让真正紧急的请求得不到资源。具体例子：解码池中一条文本请求余量充裕、一条语音请求余量逼近零，调度器把前者的预算转给后者，前者 KV 暂存一段显存；若前者在冷却窗口内再次被选中，则不得二次抢占，防止同一请求反复进出。这一判据把\"按 SLO 分配 SM 与带宽\"从口号变成了每次调度周期可执行的三分支决策。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-20\">二十 · 阶段解耦调度的失效边界与跨池代价</h3>\n<p>公式 $\\text{alloc}_j=\\arg\\max\\sum_j U_j\\ \\text{s.t.}\\ L_j\\le\\text{SLO}_j$ 的可行域并不总是非空：当各池尾延迟约束同时收紧，SM 与显存的可分配集合被切成互不相交的子集，求解退化为在约束边界上做取舍。关键一步是把 $L_j$ 写成池内排队延迟与跨池移交延迟之和，$L_j = W_j(\\lambda_j,\\mu_j) + T_{\\text{handoff}}$，其中 $W_j$ 由到达率 $\\lambda_j$ 与服务率 $\\mu_j$ 决定，$T_{\\text{handoff}}$ 是 KV cache 与状态的拷贝加同步开销。于是约束能否满足取决于 $\\mu_j$ 能否随分配的 SM 线性扩展——预填池接近线性，解码池受自回归串行性限制呈亚线性，声码器池按帧块批处理则介于两者之间。这条推导直接给出边界：当 $\\lambda_j$ 的增长快于 $\\mu_j$ 的可扩展斜率，任何分配都无法把 $L_j$ 压回 $\\text{SLO}_j$ 以内，调度器只能靠抢占把尾延迟超限请求顶到队首，代价是其他请求的驻留时间被拉长。</p>\n<p>伪代码落到可实现层面，抢占必须带两个闸门：最小驻留时间 $t_{\\min}$ 与重排冷却窗口 $t_{\\text{cool}}$。前者防止请求刚进解码池就被踢出、KV cache 反复重建；后者防止 SLO 监控在边界附近高频触发重排，造成尾延迟震荡。可写成：当 $L_j &gt; \\text{SLO}_j$ 且距上次重排超过 $t_{\\text{cool}}$，才把超限请求标记为高优先级并申请额外 SM 与带宽；被抢占请求的已解码 token 与 KV 分块保留在原池，仅冻结迭代步，避免跨池回迁。若省略 $t_{\\min}$，解码池会出现饥饿——高优先级请求持续插入，低优先级请求永远排不到 token 预算；若省略 $t_{\\text{cool}}$，重排本身成为抖动源。</p>\n<p>系统代价集中在池间带宽。跨池 KV cache 迁移的拷贝量为 $B_{\\text{kv}} = n_{\\text{layer}}\\cdot d_{\\text{head}}\\cdot n_{\\text{kv}}\\cdot s\\cdot b$（层数、头维、KV 头数、序列长度、批大小之积），每次移交都要在显存间搬运并做同步。池间带宽不足时，$T_{\\text{handoff}}$ 抬升，流水线出现气泡，预填池产出的 KV 在解码池入口排队，GPU 利用率反而低于统一批调度。声码器池的空转或积压是同一问题的另一面：帧块到达节奏由解码 token 产出速率决定，两者不匹配时声码器池要么等帧块、要么堆帧块，按帧块批处理的收益被抵消。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>观测信号</th><th>工程处置</th></tr></thead><tbody><tr><td>池间带宽不足</td><td>移交队列长度持续上升、气泡占比升高</td><td>缩小跨池批粒度，KV 分块按需迁移</td></tr><tr><td>抢占过频</td><td>尾延迟在 SLO 边界震荡</td><td>设最小驻留时间与重排冷却窗口</td></tr><tr><td>帧块节奏失配</td><td>声码器池空转或积压</td><td>按解码 token 产出速率反推帧块批大小</td></tr></tbody></table>\n<p>判断这条路线是否成立，看的是跨池带宽与显存容量能否支撑 $T_{\\text{handoff}}$ 落在 SLO 预算之内；一旦移交开销吃掉阶段解耦带来的批处理收益，退回单池连续批处理反而是更稳的选择。</p>\n<h3 id=\"alg-streamwise-multimodal-sched-sec-21\">二十一 · 负载形态的判别：什么样的请求配方才喂得饱阶段解耦</h3>\n<p>阶段解耦调度的收益不是无条件成立的，它由输入负载的统计形状决定。预填池、解码池、声码器池三者的计算特征差异极大：预填是短时高带宽的矩阵密集段，解码是长时低利用率的逐 token 迭代，声码器是按帧块的卷积/上采样密集段。只有当请求流在这三段上的到达节奏与单请求工作量比例稳定时，跨池流水线才能被填满。判别一个负载是否“适合”这套调度，看三个量：单请求的预填 token 数与解码 token 数之比、解码 token 与声码器帧块数之比、以及请求到达的并发度是否足以让每个池同时维持多个活跃批。若某模态的请求几乎不产生解码段（例如短提示、短回复的纯文本请求混在语音流里），解码池的批会被稀释到低于有效批大小的水平，池内 MMA 的利用率和权重带宽摊销同时恶化。</p>\n<p>工程上把这个判别写成配方约束。设第 $j$ 个池的活跃请求集合为 $\\mathcal{R}_j$，池的有效批大小为 $B_j$，则池被喂饱的条件是持续满足 $|\\mathcal{R}_j| \\ge B_j$，且池内请求的剩余工作量方差有界。用公式表达为调度器需要维持的驻留约束：</p>\n<div class=\"formula\">$$\\forall j:\\quad \\mathbb{E}\\big[|\\mathcal{R}_j|\\big] \\ge B_j,\\qquad \\mathrm{Var}\\big(\\text{rem}_j\\big) \\le \\sigma_j^2$$</div>\n<p>其中 $\\text{rem}_j$ 是池内请求剩余 token 或帧块数。方差约束比均值约束更关键：解码池里混入一个超长请求，会让该批的迭代步数被它拖住，其余短请求被迫陪跑，尾延迟直接被这一个请求定义。这正是统一批调度尾延迟高的根因之一，阶段解耦并不能自动消除它，只是把惩罚局部化到解码池。</p>\n<p>具体例子：一个语音对话服务同时接收朗读式长音频转写（预填极重、解码中等）与短指令问答（预填极轻、解码极短、声码器帧块少）。若两类请求按同一到达率混流进入统一池，短请求的 SLO 会被长请求的预填阻塞；拆池后短请求在预填池快速通过，但解码池仍需按 token 预算动态增删，否则短请求在解码池尾部排队。代价体现在显存上：跨池移交的 KV cache 必须常驻到解码完成，长音频请求的 KV 占用远高于短请求，池容量按均值配置就会在长请求峰值时触发抢占。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-22\">二十二 · 长度分布：重尾是配方的主要敌人</h3>\n<p>长度分布的形状直接决定批大小的可预测性。多模态生成请求的长度分布通常是重尾的：多数请求的解码 token 数落在短区间，少数长请求贡献了大部分 GPU 秒。重尾分布下，按固定批大小配置的解码池会在尾部请求到达时出现两种失效：批内迭代步数被最长请求拉长，短请求完成后的空槽无法立即被新请求填充（因为连续批处理需要等当前迭代步结束才能增删），形成槽位空转；或者调度器为保尾延迟而提前抢占长请求，把它的 KV cache 换出到显存外，产生额外的拷贝带宽开销。</p>\n<p>把重尾量化进配方的方法是看分位数比而非均值。设解码 token 数的 $p$ 分位数为 $q_p$，则配方应约束 $q_{99}/q_{50}$ 落在调度器能承受的范围内，并据此设定解码池的最小驻留时间与重排冷却窗口。伪代码思路是：每个迭代步结束后，按剩余工作量排序，优先保留剩余量接近批均值的请求，把远超均值的请求移入独立的长请求批，避免它与短请求共享迭代步。</p>\n<ul>\n<li>机制：解码池按 token 预算增删请求，预算按批内最长剩余量而非总量计算，防止单请求定义整批步数。</li>\n<li>公式：批有效利用率可写为 $\\text{util}_{\\text{batch}} = \\frac{\\sum_i \\min(\\text{rem}_i, \\text{step})}{|\\mathcal{R}|\\cdot \\text{step}}$，重尾下该值显著低于 1。</li>\n<li>代价：长请求独占批会降低解码池的 SM 占用率，但换来尾延迟可控；短请求批的吞吐上升，整体 $\\text{util}$ 未必下降。</li>\n<li>例子：视频生成请求的帧块数与语音请求的 token 数不在同一量级，若共用声码器池的批预算，语音帧块会被视频帧块挤出批，语音 SLO 先崩。</li>\n</ul>\n<p>长度分布还影响预填池的批构造。预填是计算密集段，批内序列长度差异过大时，填充浪费的算力直接体现为预填池的 SM 空转。配方上应把预填池的批按长度分桶，桶内长度方差受控，桶间按到达顺序调度。这一条与解码池的增删策略是两套逻辑，不能共用同一个批大小参数。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-23\">二十三 · 并发与批大小：三个池的批不是同一个数</h3>\n<p>并发度是配方的第三个维度。阶段解耦后，三个池的并发需求并不相同：预填池需要足够多的请求同时进入以摊薄权重读取带宽，其有效批受序列长度和 KV 写入带宽约束；解码池需要足够多的活跃序列以摊薄每步的权重带宽，其有效批受 KV cache 显存容量约束；声码器池需要帧块到达节奏与解码 token 产出匹配，其有效批受帧块大小和流水线相位约束。把同一个批大小套到三个池上，必然有一个池过载、另一个池饥饿。</p>\n<p>按 SLO 分配资源的公式给出约束形式：</p>\n<div class=\"formula\">$$\\text{alloc}_j = \\arg\\max \\sum_j U_j \\;\\;\\text{s.t.}\\;\\; L_j \\le \\text{SLO}_j$$</div>\n<p>这个优化问题的可行域由批大小与并发度共同张成。实践中把它转成两个可调旋钮：每个池的批上限 $B_j^{\\max}$ 与每个池的 SM 配额 $S_j$。$B_j^{\\max}$ 由显存与 KV 容量反推，$S_j$ 由尾延迟约束反推。解码池的 $B^{\\max}$ 若按显存上限设定而不留抢占余量，尾延迟超限时无 SM 可调，只能换出 KV，同步开销立刻上升。声码器池的 $B^{\\max}$ 若按解码池的 token 产出速率设定而不留缓冲，帧块到达抖动会直接变成池空转。</p>\n<p>具体例子：一个三模态混合服务，语音请求的解码 token 产出速率约为每步一个 token，声码器按固定帧块消费；视频请求的帧块远大于语音帧块。若声码器池用单一帧块批大小，视频帧块会把批占满，语音帧块的到达被推迟，语音首帧延迟超出 SLO。正确配方是声码器池按模态分桶、按帧块大小设不同批上限，并用最小驻留时间防止小帧块被大帧块持续挤出。代价是池内批的构造复杂度上升，调度器需要维护按模态的队列与配额，配置不当就是解码池饥饿的来源之一。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-24\">二十四 · 负载不对时的三种失效及其可观测信号</h3>\n<p>负载配方错配不会以单一故障出现，而是三种失效互相耦合。第一种是池间带宽不足导致流水线气泡：跨池 KV cache 与状态迁移的拷贝量超过池间链路带宽，预填池产出 KV 的速度被移交阻塞，解码池等 KV 而空转，$\\text{util}$ 反而低于统一批调度。可观测信号是预填池完成率与解码池启动率之间的差值持续为正，且跨池拷贝队列深度单调上升。第二种是抢占与重排配置不当导致解码池饥饿或抖动：最小驻留时间设得过短，长请求被反复换出换入，尾延迟在 SLO 边界震荡；设得过长，短请求无法插入，尾延迟同样超限。信号是解码池的换出次数与尾延迟分位数同步上升。第三种是帧块节奏失配：声码器池按帧块批处理与解码池流水线并行时，帧块到达节奏与 token 产出不匹配，声码器池要么空转要么积压。信号是声码器池的批填充率与解码池的 token 产出速率出现相位差。</p>\n<p>这三种失效的共同点是它们都不体现在单池的利用率上，而体现在池间的耦合量上。因此配方监控不能只看各池 $\\text{util}$，必须同时看跨池队列深度、换出频率、相位差三个耦合指标。SLO 判定式仍然是 $\\Pr(L_{\\text{first}} \\le L^{\\star}) \\ge 1-\\epsilon$，但 $L_{\\text{first}}$ 在多模态流式里应取首帧或首 token 的端到端时间，而非单池内部延迟，否则池内达标而端到端超限的情况会被漏掉。</p>\n<ul>\n<li>机制：SLO 监控触发抢占与重排，尾延迟超限请求优先获得 SM 与带宽，但必须配合最小驻留时间与重排冷却窗口。</li>\n<li>公式：端到端首帧延迟可分解为 $L_{\\text{first}} = L_{\\text{pre}} + L_{\\text{dec,first}} + L_{\\text{voc,first}} + L_{\\text{mig}}$，其中 $L_{\\text{mig}}$ 是跨池迁移开销，配方的关键是把 $L_{\\text{mig}}$ 压到不主导总和。</li>\n<li>代价：迁移开销随池数与模态数线性增长，显存拷贝与同步在池间带宽受限时成为瓶颈。</li>\n<li>例子：语音+文本+视频混合流中，视频帧块的 KV 与状态体积远大于语音，若共用一条跨池链路，语音请求的首帧延迟被视频迁移挤占，表现为语音 SLO 先破。</li>\n</ul>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-25\">二十五 · 配方的容量规划含义：按阶段计费与按池定容</h3>\n<p>负载配方最终要落到容量规划上。阶段解耦使容量可以按池独立核算：预填池的容量由每秒预填 token 数与 KV 写入带宽决定，解码池的容量由活跃序列数与 KV 显存决定，声码器池的容量由每秒帧块数与流水线相位裕度决定。三者不是简单相加，因为跨池流水线的吞吐由最慢池与池间带宽共同决定。配方正确的标志是三个池的容量在同一负载形状下同时接近饱和，且池间队列深度稳定在低水位；配方错误的标志是某池长期饱和而另一池长期空转，此时增加任一池的 SM 配额都不改善端到端吞吐。</p>\n<p>按 SLO 计费也依赖配方。以 token/帧块为调度单位使每个请求在各池的占用可计量，计费单元可以按阶段拆分：预填按 token、解码按 token 步、声码器按帧块。这要求调度器在跨池移交时保留请求的阶段账本，否则抢占与重排会打乱计量。工程判断是：配方未定型前不要开放按阶段计费，因为重尾负载下同一请求的池占用方差极大，按均值定价会系统性亏损。</p>\n<p>规模上限受跨池带宽与显存容量约束，材料未给出具体上限。可操作的判断是：当跨池迁移开销 $L_{\\text{mig}}$ 占到 $L_{\\text{first}}$ 的可观比例时，增加池数不再带来收益，此时应减少拆分粒度或把相邻阶段合并回同一池。配方不是越细越好，拆分的收益必须超过迁移的代价，这个比较在每个负载形状下都要重做一次。</p>\n<h3 id=\"alg-streamwise-multimodal-sched-sec-26\">二十六 · 硬件档位：按池的算术强度分档，而非按整机分档</h3>\n<p>阶段解耦之后，“硬件档位”不再是“买几台 B200”这种整机问题，而是每个池该拿什么形状的算力。判断依据是各池的算术强度与并行维度：预填池做的是条件编码与长序列注意力，矩阵乘维度大、算术强度高，吃的是 tcgen05 的 MMA 吞吐与 TMEM 容量；解码池是逐 token 自回归，每步只搬一次权重、算一个 token，算术强度低而权重带宽敏感，吃的是 HBM 带宽与 KV cache 容量；声码器池按帧块合成波形，卷积与上采样为主，算术强度居中但帧块节奏受解码池产出驱动，吃的是稳定的 SM 占用而非峰值算力。因此档位配置的第一条原则是：预填池优先高算力密度（大 MMA、宽 TMEM），解码池优先高带宽与大显存，声码器池优先可被抢占的碎片化 SM 配额。</p>\n<p>在 NVL72 这种机柜级域内，档位的另一维度是域内与域间的区分。预填池与解码池之间的 KV cache 移交走 NVLink 5 域内带宽，属于高频小消息加中量数据搬运；解码池与声码器池之间的帧块移交是高频小消息。把三个池放在同一 NVL72 域内可以把跨池拷贝压在域内链路上，代价是三个池争抢同一批 SM 与显存，档位划分退化为配额划分；把解码池独立成柜则跨池走域间链路，拷贝开销上升但配额隔离干净。工程判断是：当跨池 KV 移交量占解码池每步带宽的比例超过可接受阈值时，优先同域部署并用配额而非物理隔离来分档。</p>\n<p>档位选择要落到一个可检验的量上，即每个池的 SM 占用率与尾延迟的联合约束：</p>\n<div class=\"formula\">$$\\text{alloc}_j = \\arg\\max \\sum_j U_j \\;\\text{s.t.}\\; L_j \\le \\text{SLO}_j$$</div>\n<p>这里的 $U_j$ 是第 $j$ 个池的 GPU 利用率，$L_j$ 是该池尾延迟。注意这个式子的解不是“把 SM 全给最忙的池”，而是在尾延迟约束的边界上取利用率之和最大。举例：某混合流式请求中，预填池因条件编码长而短暂打满，解码池因 token 预算小而长期半载，若按整机平均利用率看机器很忙，但解码池的尾延迟已经贴着 SLO 边界——此时正确的档位动作是把预填池的一部分 SM 配额让给解码池，而不是给整机加卡。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-27\">二十七 · 并行拓扑：跨池流水线 + 池内张量并行，两层不要混</h3>\n<p>并行拓扑要分两层看。池间是流水线：预填产出 KV 移交解码，解码产出 token 流移交声码器按帧块合成，三段以不同节奏推进，靠缓冲区解耦。池内则是另一套并行：预填池适合张量并行（TP）切分大矩阵乘，因为它的单次前向计算量大、通信可摊薄；解码池在 TP 下每步都要做 all-reduce，而每步只产出一个 token，通信占比被放大，因此解码池更倾向小 TP 度配大 batch，用连续批处理把 all-reduce 摊到更多请求上；声码器池的并行度受帧块大小约束，TP 收益有限，更适合数据并行式的帧块批处理。</p>\n<p>两层混用的典型错误是把池间流水线的缓冲深度当成池内 batch 的替代品。缓冲深度只吸收节奏差，不提升单池吞吐；解码池的吞吐仍由每步 token 预算与 KV 容量决定。伪代码思路如下：</p>\n<ul>\n<li>调度器为每个池维护独立的 ready 队列与配额；</li>\n<li>预填池按条件长度分桶，桶内做 TP 前向，产出 KV 描述符入跨池队列；</li>\n<li>解码池每步从 ready 队列按 token 预算增删请求，超出预算的请求挂起而非丢弃；</li>\n<li>声码器池按帧块到达节奏组批，帧块不足时降批而非空转等满批。</li>\n</ul>\n<p>拓扑的代价直接体现在流水线气泡上。池间带宽不足时，KV 描述符与帧块的搬运会把三段流水线拉成串行，GPU 利用率反而低于统一批调度——这正是该机制最需要防的失败模式。一个具体例子：解码池每步产出固定数量 token，声码器池按固定帧块消费，若两者节奏比不是整数倍，帧块队列会周期性见底或溢出，声码器池在见底时空转、在溢出时反压解码池，尾延迟在 SLO 边界震荡。解法是让声码器池的批大小随队列水位浮动，并把解码池的 token 预算做成可调旋钮而非固定值。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-28\">二十八 · 量化方案：按池独立选格式，跨池边界保持数值契约</h3>\n<p>量化不能整机一刀切，因为三个池的数值敏感度不同。预填池的条件编码对激活离群值敏感，适合 NVFP4 做权重、FP8 做激活的混合方案，微缩放格式把块级尺度压进张量核心的读取路径，减少反量化开销；解码池的自回归对权重精度更敏感而对激活动态范围要求低，可用 NVFP4 权重配 FP8 KV；声码器池的波形合成对相位与幅度细节敏感，低位宽量化会直接反映为可听的失真，因此声码器池通常保留 FP8 甚至更高精度，量化的收益主要来自批处理而非位宽。</p>\n<p>跨池边界是量化方案最容易出问题的地方。预填池产出的 KV cache 以某种精度写入，解码池以另一种精度读取，中间若发生一次反量化再量化，就多了一次全量 KV 的读写往返——在 KV 容量受限的场景下，这次往返的显存带宽代价可能吃掉量化省下的全部收益。工程做法是让 KV 的存储格式在跨池移交时保持不变，只在消费端做一次反量化，并把反量化的融合进注意力算子的读取路径。同理，解码池到声码器池的 token 流是离散码本索引，量化方案应作用于码本嵌入而非索引本身，避免索引被数值化后再量化引入码本错位。</p>\n<p>量化档位的选择要与 KV 策略联动，而不是独立调参。若解码池采用低位宽 KV，KV 容量上升、可容纳的并发请求数上升，但每步注意力的反量化开销上升，尾延迟的方差变大；此时调度参数应相应收紧 token 预算、放大最小驻留时间，避免请求在精度切换边界上反复进出。一个具体判断：当解码池的 KV 显存占用成为并发上限的约束时，优先压 KV 位宽；当解码池的每步延迟方差成为 SLO 约束时，优先保 KV 精度而压权重位宽。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-29\">二十九 · KV 策略：容量、迁移与驻留三件事分开配</h3>\n<p>KV 策略在本机制里被拆成三件独立的事，混在一起配就会互相打架。第一是容量：解码池的 KV 容量决定并发上限，容量按池独立配置意味着预填池可以不留 KV 驻留、只做移交，解码池则要按最坏条件长度预留。第二是迁移：跨池 KV 移交的粒度应是描述符加数据块，而非整段 KV 全量拷贝；预填池按条件分段产出 KV，解码池按需拉取，未消费的分段留在预填池侧或落入分级存储。第三是驻留：被抢占的请求其 KV 不能立即释放，否则重排后要重新预填，尾延迟超限请求的优先恢复就失去意义。</p>\n<p>驻留策略与抢占策略必须成对设计。SLO 监控触发抢占时，被抢占请求的 KV 进入驻留区并打上时间戳；重排冷却窗口内的请求不允许再次被抢占，最小驻留时间保证它至少获得一段连续 SM 时间。缺少这两个参数，解码池会在 SLO 边界上反复抢占与恢复，形成抖动——每次恢复都要重新拉取 KV，跨池拷贝开销叠加，尾延迟不降反升。伪代码层面的约束是：抢占决策必须同时检查目标请求的驻留年龄与冷却窗口剩余时间，两者任一不满足则改为降批而非抢占。</p>\n<p>KV 策略的代价可以用一个比值来盯：跨池 KV 搬运字节数除以解码池每步的有效计算字节数。这个比值上升意味着流水线的搬运开销开始侵蚀解码池的算力配额，此时应减少跨池分段数、增大单次移交块，或把预填与解码合并到同域以缩短链路。具体例子：视频模态的条件编码产出长 KV，若按短分段高频移交，描述符消息的数量会压垮跨池队列；改为按镜头边界做大块移交，消息数下降而单次拷贝量上升，整体搬运开销反而更可控。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-30\">三十 · 调度参数：把 SLO 约束翻译成四个旋钮</h3>\n<p>调度参数不是一堆独立超参，而是 SLO 约束在四个旋钮上的投影：token 预算（解码池每步接纳的 token 总量）、帧块批大小（声码器池的组批上限）、最小驻留时间（被抢占请求的保护期）、重排冷却窗口（同一请求两次重排的最小间隔）。这四个旋钮之间存在耦合：token 预算放大提升解码池吞吐但拉长单请求的步间间隔，尾延迟方差上升；帧块批大小放大提升声码器池利用率但增加帧块排队，与解码池的节奏失配更严重；最小驻留时间与冷却窗口共同决定抢占的频率上限，设得过短则抖动，设得过长则尾延迟超限请求得不到及时救援。</p>\n<p>参数整定的可复现思路是：先固定量化与 KV 策略，再按池单独扫旋钮，最后联调。单池扫描时盯住该池的尾延迟分位与利用率，找到尾延迟刚好贴住 SLO 的旋钮取值作为初值；联调时只动 token 预算与帧块批大小这一对，观察跨池队列水位是否出现周期性见底或溢出，出现则说明两池节奏比需要调整，优先改帧块批大小的浮动范围而非改 token 预算的绝对值。整个过程中抢占相关参数保持保守，直到流水线节奏稳定后再逐步收紧。</p>\n<p>容量规划在这个框架下变成对旋钮的预算分配：给定 SM 总量与显存总量，先按 SLO 约束解出各池的 $U_j$ 与 $L_j$ 可行域，再把可行域翻译成旋钮的取值范围。公式层面的判据仍是那条带约束的最大化，但工程上更常用的是它的对偶形式——每个池的尾延迟对 SM 配额的边际改善，边际改善大的池优先获得配额。举例：当声码器池因帧块到达不匹配而空转时，它的边际改善很高，但增加 SM 配额并不能解决节奏问题，此时正确的动作是调帧块批大小而非加配额；反之解码池因 KV 容量不足而挂起请求时，加配额或压 KV 位宽才是有效动作。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-31\">三十一 · 一个可复现的配置流程</h3>\n<p>把上述四块拼成一条可复现的流程，顺序不能颠倒。第一步定模态组合与阶段划分，确认预填、解码、声码器三段是否都需要独立池——若某模态的声码器与解码在同一模型内且节奏天然同步，则不必拆池，拆了反而多一次跨池移交。第二步按算术强度给每个池选硬件档位与并行拓扑，预填池定 TP 度、解码池定 TP 度与 batch 上限、声码器池定帧块批处理形态。第三步按池独立定量化格式，并在跨池边界上锁定 KV 与码本索引的数值契约。第四步配 KV 策略的三件事：容量预留、分段移交粒度、驻留区大小。第五步扫调度四旋钮，先单池后联调，联调阶段只动节奏相关的一对参数。第六步接入 SLO 监控与抢占重排，设置最小驻留时间与冷却窗口，并用跨池队列水位与尾延迟分位作为回归指标。</p>\n<p>这条流程里最容易被跳过的是第三步的数值契约与第四步的驻留区大小，而它们恰恰是失败模式的高发区。跨池 KV 精度不一致会引入隐性反量化往返，驻留区过小会让抢占变成重新预填。一个具体的配置判断：当解码池的并发上限由 KV 容量决定、且跨池搬运比值已经偏高时，不要继续压 KV 位宽来换并发，而应缩短预填池到解码池的移交链路（同域部署或增大移交块），因为此时瓶颈在搬运而非容量。配置的终点不是一组固定数值，而是一组带约束的旋钮范围加一条回归判据：跨池队列水位不出现周期性见底或溢出、各池尾延迟分位稳定在 SLO 之内、抢占频率低于冷却窗口允许的上限。</p>\n<h3 id=\"alg-streamwise-multimodal-sched-sec-32\">三十二 · 跨池迁移：显存拷贝与同步的硬账</h3>\n<p>阶段解耦把一条请求切成预填、解码、声码器三段，代价首先落在池与池之间的状态搬运上。预填池产出的是该请求的 KV cache 与条件编码张量，解码池要接着迭代，声码器池要按帧块取隐状态——每一次移交都是一次显存写+读，且必须带同步语义，否则解码池会在 KV 尚未落地时读到半成品。这笔账要按字节算：一个请求的 KV cache 规模正比于层数、头数、头维度与已缓存 token 数，跨池迁移的有效带宽不是 HBM 带宽，而是“HBM→HBM 拷贝 + 事件同步 + 接收侧可见性”的合成值，通常远低于单池内的原地读写。</p>\n<div class=\"formula\">$$T_{\\text{mig}} = \\frac{B_{\\text{kv}}}{\\text{BW}_{\\text{pool2pool}}} + T_{\\text{sync}},\\quad B_{\\text{kv}} = 2 \\cdot n_{\\text{layer}} \\cdot n_{\\text{kvhead}} \\cdot d_{\\text{head}} \\cdot n_{\\text{tok}} \\cdot b_{\\text{elem}}$$</div>\n<p>工程上的判断很直接：当 $T_{\\text{mig}}$ 与解码池一个迭代步的时长同量级时，迁移就不再是“后台开销”，而是流水线节拍的一部分。此时要么把预填与解码放在同一 GPU 上用分区 SM 隔离（省掉跨卡拷贝，只付同步），要么把 KV 按块分片、只迁移解码池即将消费的那一段，用流水掩盖剩余部分。反过来，如果盲目把三个池摊到三组 GPU 上，跨池链路一旦不是 NVLink 5 域内而是跨节点，$T_{\\text{mig}}$ 会直接吃掉预填池换来的利用率收益。规模上去以后第一个崩的地方往往不是算力，而是这条迁移路径的有效带宽。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-33\">三十三 · 池间带宽竞争与流水线气泡</h3>\n<p>三池流水并行时，预填池、解码池、声码器池各自都在打 HBM 与链路的主意：预填池是计算密集但一次性写入大块 KV，解码池是低算术强度、每步都要读全部 KV，声码器池是帧块级的卷积/反卷积，读写隐状态频繁。三者共享同一条池间链路时，带宽分配就变成了调度问题，而不是容量问题。设第 $j$ 池在时刻 $t$ 的带宽需求为 $b_j(t)$，链路容量为 $C$，则可行条件为 $\\sum_j b_j(t) \\le C$；一旦某个时刻预填池的批量突增，解码池的 KV 读取就被挤到排队，迭代步时长抖动，尾延迟随之上翘。</p>\n<p>更隐蔽的是气泡：声码器池按帧块消费，帧块到达节奏由解码池的 token 产出速率决定。解码池因抢占或批增删出现一个长迭代步，声码器池在该窗口内无帧可合成，SM 空转；反之解码池短步密集产出时，声码器池积压，帧块在队列里等待，端到端延迟被队列深度而非计算本身主导。这不是靠加机器能解的，因为气泡的根源是两池节拍不匹配。可行做法是给声码器池设一个帧块水位窗口（低水位触发预取、高水位触发解码池限速），把两池的耦合从“事件驱动”改成“水位驱动”，代价是引入一个可调的缓冲延迟，需在 SLO 预算里显式扣除。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-34\">三十四 · 抢占与重排：抖动从哪里来</h3>\n<p>SLO 监控触发抢占时，被抢占的请求要释放 SM 与显存，其 KV cache 要么换出到 host 或远端，要么原地保留等重排。这里有两个必须量化的代价。其一是换出/换入的带宽代价：一次抢占-恢复周期搬运的字节数约等于 $2 B_{\\text{kv}}$，若抢占频率为 $f$，则稳态带宽占用为 $2 f B_{\\text{kv}}$，这部分带宽不与有效计算共享，纯属损耗。其二是抖动：若重排冷却窗口短于解码池一个批周期的时长，同一请求会在“被抢占—被恢复—再被抢占”之间反复，尾延迟在 SLO 边界震荡，监控看到的是一条锯齿曲线而非稳定收敛。</p>\n<p>因此抢占策略必须带两个参数：最小驻留时间 $T_{\\text{dwell}}$（请求进入解码池后至少驻留多久才可被抢占）与重排冷却窗口 $T_{\\text{cool}}$（同一请求两次重排之间的最小间隔）。经验判据是让 $T_{\\text{dwell}}$ 不小于解码池一个完整批迭代的时长，让 $T_{\\text{cool}}$ 不小于声码器池一个帧块水位周期的时长。配置不当的典型症状是解码池饥饿：高优先级的长请求持续抢占，短请求永远排不上，池内批大小塌缩，SM 利用率掉到低位——此时 $\\text{util}$ 下降并非因为没活干，而是因为活被反复打断。</p>\n<div class=\"formula\">$$\\text{util}=\\frac{\\sum \\text{SM}_{\\text{busy}}}{\\text{SM}_{\\text{total}}},\\quad \\text{SLO}_{\\text{ok}} = \\Pr\\big(L_{\\text{first}} \\le L^{\\star}\\big) \\ge 1-\\epsilon$$</div>\n<p>注意这两个指标的方向可以相反：把抢占调激进，尾延迟的均值可能下降但方差上升，$\\Pr(L_{\\text{first}} \\le L^{\\star})$ 反而变差；把抢占调保守，尾延迟方差收敛但均值抬升，同样击穿 SLO。资源分配式 $\\text{alloc}_j = \\arg\\max \\sum_j U_j \\;\\text{s.t.}\\; L_j \\le \\text{SLO}_j$ 的求解因此不是一次性优化，而是带滞回的在线控制——每次重排都要付出上面那笔 $2 f B_{\\text{kv}}$ 的带宽税。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-35\">三十五 · 功耗与热：被忽略的第三约束</h3>\n<p>三池并行意味着 GPU 的功耗预算被切成三份，而三池的功耗特征完全不同：预填池是短时高功率的矩阵密集段，解码池是长时中功率的访存受限段，声码器池是帧块级的中低功率段。当预填池批量突增时，其瞬时功率抬升会触发整卡的功耗封顶，解码池被迫降频，迭代步时长被拉长——这是一条从功耗回到延迟的耦合路径，在单池统一批调度里不明显，在解耦后因为池间共享同一张卡的功率包络而放大。</p>\n<p>工程上的处理是把功耗当作与 SM、显存并列的第三种可分配资源：给预填池设功率上限而非 SM 上限，让其在封顶内自行调节批大小；解码池则优先保频率稳定，因为其延迟对频率敏感而对批大小相对宽容。若三池分布在不同 GPU 上，则每张卡的功率包络独立，耦合减弱，但跨池迁移代价回升——这正是第一部分那条迁移账与本节功耗账之间的权衡点。规模上去后，机柜级功率封顶（NVL72 整柜）会让这个耦合从卡内上升到柜内，此时池的物理放置比池的算法配置更能决定尾延迟。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-36\">三十六 · 规模上限：先崩的是哪一环</h3>\n<p>把请求量按倍数放大，各环节的余量衰减速率不同，可以排出一个崩溃顺序。最先饱和的是池间有效带宽：$T_{\\text{mig}}$ 随并发请求数线性增长，而链路容量固定，一旦 $\\sum_j b_j(t) &gt; C$ 成为常态，预填池的产出就被迫限速，解码池开始等 KV，尾延迟以队列深度而非计算时长计价。第二个崩的是显存容量：三池各自持有 KV 与中间状态，池间缓冲（帧块队列、待迁移 KV 块）随并发线性膨胀，显存碎片化让可用块数下降，最终触发更频繁的抢占，把第三节那笔带宽税再乘一遍。第三个才是 SM 利用率：当迁移与抢占把批大小压到很小，$\\text{util}$ 才明显下滑——也就是说，util 低往往是前两环崩掉的结果，而不是原因。</p>\n<p>因此容量规划不能只按 SM 数做，要按“每请求的迁移字节数 × 并发数 ÷ 池间有效带宽”先算出带宽可支撑的并发上限，再按“每请求 KV 字节 × 并发数 ÷ 池可用显存”算显存上限，两者取小。声码器池的帧块队列深度是第三个约束，它决定积压延迟的上界。三个上限里最小的那个就是这套解耦架构的实际规模天花板，扩容时优先补最短的那块板，而不是平均加卡。</p>\n<table class=\"mini\"><thead><tr><th>环节</th><th>饱和信号</th><th>主导代价</th><th>优先手段</th></tr></thead><tbody><tr><td>池间迁移带宽</td><td>解码池等 KV、迭代步抖动</td><td>延迟（队列化）</td><td>同卡分区、KV 分块流水迁移</td></tr><tr><td>池显存容量</td><td>抢占频率上升、块碎片化</td><td>带宽税 $2fB_{\\text{kv}}$</td><td>池独立量化档位、缓冲水位收紧</td></tr><tr><td>帧块队列</td><td>声码器空转或积压</td><td>端到端延迟上界</td><td>水位驱动限速、解码池节拍对齐</td></tr><tr><td>功率包络</td><td>预填突增后解码降频</td><td>迭代步时长</td><td>预填池功率封顶、池物理分置</td></tr></tbody></table>\n<p>这张表的用法是诊断而非罗列：监控上若看到解码池迭代步时长的方差先于均值恶化，指向迁移带宽；若看到抢占次数与尾延迟同向爬升，指向显存；若看到声码器池 SM 空闲率与解码池批大小反相，指向节拍失配。三种症状对应三种不同的扩容动作，混着加卡只会把最短的板暂时垫高，然后在下一次负载抬升时以同样的顺序再崩一遍。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-37\">三十七 · 调度器的可观测性设计</h3>\n<p>要让上面这些代价可管，调度器必须暴露池级的细粒度指标，而不是只报端到端延迟。最小集合包括：每池的批大小时间序列、每池的 KV 迁移字节数与迁移等待时长、抢占次数与平均驻留时间、帧块队列水位、每卡功率与频率。这些指标要能按请求标签聚合，否则无法判断尾延迟是来自某个模态的长请求还是来自池间耦合。伪代码层面的判据可以写成：当某池的迁移等待时长分位数超过其迭代步时长的固定比例时，触发池合并或分片迁移；当抢占次数在冷却窗口内超过阈值时，自动放宽 $T_{\\text{dwell}}$。</p>\n<p>最后落在一条工程判断上：阶段解耦的收益来自“各池按自身计算特征批处理”，而其全部代价都可以归到三个可测量的量——迁移字节、抢占频率、节拍失配度。调度器的复杂度应当只花在对这三个量的在线估计与滞回控制上，任何超出这个范围的策略（例如跨池的全局最优重排）都会因为状态空间过大而退化为抖动源。规模上去以后先崩的是池间带宽，而带宽问题的解不在带宽本身，在于把迁移量按消费节奏切块、把池的物理位置按功率与链路拓扑摆对。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-38\">三十八 · 跨池流水线的代价拐点：带宽、显存与尾延迟震荡</h3>\n<p>阶段解耦把统一批调度的阻塞拆开了，但代价是把一次请求的生命周期切成三段跨池流水线，KV cache 与中间状态必须在池间搬运。设单请求状态量为 $S$（KV 加音频/视频条件嵌入），池间有效带宽为 $B$，则迁移开销为 $T_{\\text{mig}}=S/B$，它与该池的计算时间 $T_{\\text{comp}}$ 的比值决定流水线是否出现气泡：当 $T_{\\text{mig}}/T_{\\text{comp}}$ 逼近 1，预填池产出的 KV 来不及被解码池消费，解码池被迫空转等数据，SM 利用率不升反降。这是规模上去后最先崩的地方——不是算力不够，而是池间带宽与显存容量先到顶。多模态请求的状态量远大于纯文本，视频条件嵌入与音频码本状态叠加后，跨池拷贝的显存带宽占用会与解码池的权重读取争抢同一份 HBM 带宽。</p>\n<p>第二处先崩的是尾延迟。SLO 监控触发抢占与重排，尾延迟超限请求优先获得 SM 与带宽，但抢占本身要保存与恢复被逐出请求的状态，这笔显存拷贝又回到带宽账上。若重排没有最小驻留时间与冷却窗口，解码池会在“逐出—重入”之间高频抖动，尾延迟在 SLO 边界反复震荡，$\\text{SLO}_{\\text{ok}}=\\Pr(L_{\\text{first}}\\le L^{\\star})\\ge 1-\\epsilon$ 的达标率反而随负载上升而下降。声码器池按帧块批处理、与解码池流水线并行时，帧块到达节奏由解码 token 产出速率决定，两者不匹配就出现声码器池空转或帧块积压，积压的帧块占住显存，进一步压缩解码池的 KV 预算。</p>\n<table class=\"mini\"><thead><tr><th>规模上升时先触顶的资源</th><th>触发条件</th><th>系统表现</th></tr></thead><tbody><tr><td>池间带宽</td><td>状态迁移时间接近池内计算时间</td><td>流水线气泡，利用率下降</td></tr><tr><td>显存容量</td><td>帧块积压 + 多池独立 KV 配置</td><td>解码池批大小被压缩</td></tr><tr><td>抢占开销</td><td>重排无冷却窗口</td><td>尾延迟在 SLO 边界震荡</td></tr></tbody></table>\n<p>工程判断落在容量规划的口径上：按 $\\text{alloc}_j=\\arg\\max\\sum_j U_j$ s.t. $L_j\\le\\text{SLO}_j$ 分配 SM 与显存时，必须把跨池迁移带宽作为独立约束写进规划，而不是事后调参。可行的做法是给每个池设状态驻留上限与迁移预算，把 $T_{\\text{mig}}$ 纳入批大小求解，使预填池的产出速率与解码池的消费速率在稳态下匹配；声码器池则以帧块水位线触发反压，避免积压穿透到显存。规模上限因此不由单池算力决定，而由最窄的那段跨池带宽与最紧的那个池的显存余量共同决定。</p>\n<h3 id=\"alg-streamwise-multimodal-sched-sec-39\">三十九 · 精度问题：跨池迁移中的数值漂移与帧块错位</h3>\n<p>阶段解耦把一次请求切成预填、解码、声码器三段，数值路径也随之被切成三段。精度故障几乎都发生在切缝上，而不是某一段内部。典型形态有三种：其一，预填池产出的 KV cache 与解码池加载时的量化档位不一致——预填按池内独立配置写出的 cache，若解码池以不同微缩放粒度读入，注意力 logits 会出现系统性偏移，表现为合成语音的基频抖动或文本侧重复短语；其二，声码器池按帧块批处理，若帧块边界与解码池 token 产出边界未对齐，波形拼接处出现周期性爆音，这是帧块错位而非数值误差；其三，跨池状态迁移时把 FP8 中间态直接落盘再读回，缺少反量化步骤，导致长请求后半段的能量包络塌陷。</p>\n<p>诊断这类问题不能靠听感抽查。工程做法是在每个池的出口挂一个轻量探针，对固定 prompt 集合计算逐阶段的可比统计量：预填池出口的 KV 均值与方差、解码池每 N 个 token 的 logits 熵、声码器池每帧块的能量与过零率。三者各自与基线快照比对，任一统计量偏离超过阈值即判定该池精度异常，从而把故障定位到具体池而非整条流水线。代价是探针本身占用 SM 与带宽：每池常驻一个极小 batch 的参考请求，在解码池上相当于挤占约一个 token 预算的批容量，必须计入容量规划，否则探针本身会成为尾延迟尖刺的来源。</p>\n<div class=\"formula\">$$\\Delta_{\\text{drift}} = \\big|\\,\\mathbb{E}[h_{\\text{pool}}] - \\mathbb{E}[h_{\\text{ref}}]\\,\\big| \\;/\\; \\sigma_{\\text{ref}}$$</div>\n<p>其中 $h$ 为阶段出口隐状态或 KV 统计量，$\\sigma_{\\text{ref}}$ 为基线快照标准差。判据是 $\\Delta_{\\text{drift}}$ 超过设定倍数即触发回滚。回滚粒度必须按池而非按服务：把解码池单独切回上一版量化配置，预填池与声码器池不动，这样回滚只损失解码池的重启时间，而不必清空全部在途请求的 KV cache。举例：某次变更把解码池 KV 从 FP8 切到 NVFP4 以省显存，探针在 30 秒内报出 logits 熵偏移，调度器将解码池标记为不健康、停止接纳新请求、把在途请求的 KV 以旧格式重放预填，声码器池因流水线并行继续消化已产出的帧块，用户侧只感知到一次轻微停顿而非整段失败。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-40\">四十 · OOM：显存账本的三处漏算</h3>\n<p>OOM 在多模态流式服务里极少是单池超限，几乎都是跨池账本没算清。三处漏算最常见：预填池为批量条件编码临时申请的激活显存未在请求移交后立即释放，残留到解码池扩容时撞上水位；跨池 KV cache 迁移使用双缓冲，同一份 KV 在源池与目标池同时驻留，峰值显存是稳态的两倍；声码器池按帧块批处理时，波形输出缓冲按最大帧块预留，而实际到达的帧块远小于上限，形成长期闲置的显存碎片。</p>\n<p>可控的做法是把显存当作调度变量而非静态配额。每个池维护一份显存账本，记录稳态占用、迁移峰值、碎片水位三个量，调度器在增删请求前先查账本再决定是否接纳。接纳判据可写成：新请求的 KV 预估增量加上迁移峰值不得超过该池显存上限减去安全水位。安全水位不是固定比例，而应随池的批抖动幅度动态调整——抖动大的池需要更高水位来吸收突发。代价是水位抬高直接压低批容量，进而压低该池 SM 利用率，这是显存与吞吐之间的硬取舍。</p>\n<ul>\n<li>预填池：激活显存按请求移交即释放，禁止跨请求复用未清零缓冲。</li>\n<li>解码池：KV 迁移采用单缓冲加就地转换，牺牲迁移带宽换显存峰值减半。</li>\n<li>声码器池：帧块输出缓冲按滑动窗口分配，窗口大小由实测帧块到达分布决定而非按上限预留。</li>\n</ul>\n<p>具体例子：视频帧块解码的请求在声码器池触发 OOM，账本显示稳态占用不高但迁移峰值翻倍，原因是解码池向声码器池移交时保留了源侧副本等待确认。改为移交即释放、确认信号走独立控制通道后，峰值回落，池恢复接纳。这里付出的代价是控制通道的同步开销增加，池间流水线在移交点出现短暂气泡，需要用重排冷却窗口吸收。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-41\">四十一 · 批抖动与路由不均：抢占策略的两个反面</h3>\n<p>批抖动是阶段解耦的固有副作用。解码池按 token 预算动态增删请求，预算本身随 SLO 监控调整；一旦抢占触发过于频繁，批组成在相邻迭代间反复变化，每次变化都伴随 KV 重排与显存拷贝，SM 有效利用率被这些非计算操作吃掉。抖动在指标上表现为批大小的时间序列高频振荡，同时 $\\text{util}$ 下降而尾延迟不降。防抖的核心是给抢占加两个闸门：最小驻留时间，请求进入解码池后至少驻留若干迭代才可被抢占；重排冷却窗口，一次重排后若干迭代内不再触发同类重排。两个闸门都以迭代数为单位而非墙钟时间，避免负载变化时闸门失效。</p>\n<div class=\"formula\">$$\\text{util}=\\frac{\\sum \\text{SM}_{\\text{busy}}}{\\text{SM}_{\\text{total}}},\\qquad \\text{jitter}=\\mathrm{Var}\\big(b_t\\big)$$</div>\n<p>路由不均是另一类故障，表现为某些池长期高水位、另一些长期空转。根因通常是请求拆分时按模态而非按计算特征分配：语音请求的预填短、解码长，视频请求的预填长、帧块产出密集，若调度器只看模态标签而不看阶段负载，就会把同类请求堆到同一池。诊断靠池级利用率的方差而非均值——均值健康掩盖不了方差过大。修法是在拆分入口加一层按阶段负载的再平衡，把预填任务与解码任务分别按各自池的当前水位路由，而非按请求整体路由。</p>\n<p>具体例子：语音加文本混合流中，文本侧解码 token 产出快、语音侧声码器帧块产出慢，若按请求整体路由，声码器池积压而解码池空转。改为按阶段路由后，解码池的 token 预算可跨请求共享，声码器池按帧块到达节奏独立批处理，两池利用率同时抬升。代价是拆分入口需要维护两套水位视图，控制面开销增加，且跨池流水线的气泡点从一处变为多处，需要更细的监控粒度。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-42\">四十二 · 尾延迟尖刺：SLO 边界的震荡与诊断</h3>\n<p>尾延迟尖刺在阶段解耦架构里有明确的结构性来源：池间带宽不足时流水线出现气泡，气泡沿数据流向后传递并在声码器池出口放大为可感知的停顿；抢占与重排配置不当时，尾延迟在 SLO 边界反复震荡，超限请求获得优先资源后立刻回落，下一批请求又超限，形成锯齿。诊断这两类尖刺要区分“带宽型”与“策略型”：带宽型尖刺伴随跨池迁移队列深度上升与池间拷贝带宽打满，策略型尖刺伴随抢占次数与重排次数同步上升而迁移队列平稳。</p>\n<p>SLO 判据本身要按阶段拆开，不能只看端到端。端到端达标可能掩盖某一阶段长期贴着上限运行，一旦负载微增就整体越界。分阶段判据写成首段延迟与各池尾延迟的联合约束：</p>\n<div class=\"formula\">$$\\text{SLO}_{\\text{ok}} = \\Pr\\big(L_{\\text{first}} \\le L^{\\star}\\big) \\ge 1-\\epsilon$$</div>\n<p>工程上把 $L_{\\text{first}}$ 拆成预填出口时刻、首个解码 token 时刻、首个帧块输出时刻三个观测点，任一观测点的尾部分位数越界即判定该阶段为尖刺源。监控采样必须按请求而非按时间窗，否则低频的长请求尖刺会被高频短请求稀释。代价是分阶段观测点需要在流水线上插入时间戳，时间戳写入本身有同步开销，且在抢占重排时时间戳的因果顺序可能被打乱，需要以请求 ID 加阶段序号做排序键。</p>\n<p>具体例子：某视频流式请求的首帧延迟尖刺，分阶段观测显示预填出口正常、首个解码 token 正常、首个帧块输出越界，定位到声码器池帧块到达节奏与解码 token 产出不匹配导致空转等待。修法是给声码器池设最小帧块批阈值，低于阈值时等待而非立即合成，用少量首帧延迟换池利用率。回滚路径是把该阈值恢复为激进值，牺牲利用率保首帧。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-43\">四十三 · 监控面与回滚：按池的灰度与状态重放</h3>\n<p>监控面必须与调度单位对齐。以 token/帧块为调度单位意味着监控也应以 token/帧块为采样粒度，而不是以请求为粒度做黑盒统计。每个池暴露四类指标：批组成的时间序列（批大小、增删速率）、显存账本三项、跨池迁移队列深度与拷贝带宽、分阶段尾延迟分位数。四类指标联合判读才能区分前述故障：批组成振荡加利用率下降是抖动，迁移队列上升加带宽打满是气泡，尾延迟锯齿加抢占计数上升是策略型尖刺。</p>\n<p>回滚的设计原则是“按池灰度、按状态重放”。按池灰度指每次变更只作用于一个池，其余池保持上一版配置，观测窗口内该池指标不劣化才推进到下一池。按状态重放指回滚时不要求请求从头开始：预填池回滚后，在途请求的 KV cache 若格式兼容则直接沿用，不兼容则以旧配置重放预填；解码池回滚后，已产出的 token 保留，仅从当前迭代起重置批组成；声码器池回滚后，已合成的帧块保留，未合成的帧块按新配置重排。这样回滚的代价被限制在单池重启加一次状态转换，而非全服务清空。</p>\n<table class=\"mini\"><thead><tr><th>故障</th><th>首要指标</th><th>回滚粒度</th><th>代价</th></tr></thead><tbody><tr><td>精度漂移</td><td>阶段出口统计量偏移</td><td>单池量化配置</td><td>该池重启，KV 重放</td></tr><tr><td>OOM</td><td>显存账本迁移峰值</td><td>单池缓冲策略</td><td>迁移同步开销上升</td></tr><tr><td>批抖动</td><td>批大小方差、util</td><td>抢占闸门参数</td><td>批容量下降</td></tr><tr><td>路由不均</td><td>池利用率方差</td><td>拆分入口路由规则</td><td>控制面开销上升</td></tr><tr><td>尾延迟尖刺</td><td>分阶段尾分位数</td><td>单池批阈值</td><td>首段延迟或利用率损失</td></tr></tbody></table>\n<p>回滚闸门本身要有防误触发机制：单次指标越界不触发回滚，需连续多个观测窗口同向越界且伴随至少一个次级指标异常。这是为了避免探针噪声与瞬时负载尖峰引发无谓重启——重启一个池的代价是该池在途请求的状态转换与流水线气泡，频繁误回滚会把稳定性问题转化为可用性问题。工程判断落在闸门参数上：观测窗口长度应大于池的最小驻留时间与重排冷却窗口之和，否则回滚判定会与调度器的防抖机制互相干扰，形成“回滚—恢复—再回滚”的循环。</p>\n<h3 id=\"alg-streamwise-multimodal-sched-sec-44\">四十四 · 对照维度：把“同族”拆成四个可判定的轴</h3>\n<p>多模态流式服务的调度算法并不是一条连续谱，而是围绕四个互相独立的决策轴各自演化出来的变体。选型失败往往不是选错了“最好的算法”，而是把四个轴上的取值混搭成了互相打架的组合。这四个轴是：<strong>解耦粒度</strong>（单池统一批处理 vs 按阶段拆池）、<strong>调度单位</strong>（请求级 vs token/帧块级）、<strong>抢占语义</strong>（无抢占的 FIFO、有最小驻留时间的软抢占、带重排冷却窗口的硬抢占）、<strong>跨阶段耦合方式</strong>（串行移交 vs 流水线并行 vs 单模型内多 token 预测）。</p>\n<p>本条目（阶段解耦 + token/帧块调度 + SLO 触发抢占 + 跨池流水线）在四个轴上的取值是：拆池、块级、软抢占带冷却、流水线并行。相邻算法各自落在不同的格子里——统一连续批处理是“单池 + 请求级 + 无抢占 + 串行”；FlashTTS 一类的 MTP 流式方案是“单池 + 子 token 级 + 无抢占 + 模型内多 token 预测”。把这三者放进同一张表，选型就变成查表而非辩论。</p>\n<p>判定的代价信号必须落到可测量量上。拆池的收益上限由各池计算特征差异度决定：预填是 compute-bound 的大矩阵乘，解码是 memory-bound 的逐 token 迭代，声码器是固定帧率的卷积合成，三者的 SM 占用曲线形状完全不同。若把三者塞进一个池，批处理只能取三者需求的最小公倍数，SM 利用率被最“瘦”的阶段拖住。用 <span class=\"formula\">$$\\text{util}=\\frac{\\sum \\text{SM}_{\\text{busy}}}{\\text{SM}_{\\text{total}}}$$</span> 度量，单池方案的 util 上限就是各阶段 util 的加权最小值，而拆池后每个池各自逼近自己的上限。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-45\">四十五 · 决策表：五类同族算法的适用条件</h3>\n<p>下表把同族算法按“何时该选它”而非“它是什么”来组织。每一行的判据都是可以在部署前用一次 profiling 回答的问题，不需要先上线再试。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>算法族</th><th>解耦/单位/抢占/耦合</th><th>选它的充分条件</th><th>不该选它的信号</th><th>主要代价位</th></tr>\n</thead>\n<tbody>\n<tr><td>统一连续批处理（单池）</td><td>单池 / 请求级 / 无 / 串行</td><td>各阶段计算特征接近；模态单一；SLO 只约束端到端而非分阶段</td><td>预填与解码互相阻塞导致尾延迟抖动；分阶段 SLO 无法用单一批大小满足</td><td>尾延迟（预填长请求阻塞解码迭代）</td></tr>\n<tr><td>本条目：阶段解耦 + 块级调度</td><td>拆池 / token·帧块 / 软抢占 / 流水线</td><td>语音+文本+视频混合；三阶段 compute/memory/固定帧率特征差异显著；SLO 按阶段分别给定</td><td>跨池带宽不足以承载 KV 与状态迁移；池数超过可管理粒度导致配置抖动</td><td>显存拷贝与同步（跨池 KV 迁移）、池间气泡</td></tr>\n<tr><td>MTP 流式（单模型内多 token 预测）</td><td>单池 / 子 token / 无 / 模型内并行</td><td>单一模型已具备多 token 头；不想引入跨池状态迁移；追求单卡内确定性延迟</td><td>模型无 MTP 头需改造；多模态阶段仍需独立资源配比</td><td>模型显存（额外预测头）、接受率不足时的无效计算</td></tr>\n<tr><td>分块编解码器推理</td><td>单池 / 帧块 / 无 / 串行</td><td>瓶颈在编解码器本身而非调度；帧块大小可静态确定</td><td>解码与合成节奏不匹配造成空转——正是需要流水线的场景</td><td>帧块边界处的带宽突发</td></tr>\n<tr><td>投机解码（自回归码本 LM）</td><td>单池 / token / 无 / 串行</td><td>解码阶段是唯一瓶颈；有可用的草稿模型或草稿头</td><td>预填占比高；多模态阶段拆分收益大于投机收益</td><td>草稿模型显存、验证失败的算力浪费</td></tr>\n</tbody>\n</table>\n<p>读表的方式是自上而下排除：先用“阶段特征是否接近”决定要不要拆池；拆池后再用“跨池带宽是否够”决定流水线还是串行移交；最后用“是否有 MTP 头”决定是否退回单池内的多 token 预测。任何一步的否定答案都直接落到下一行，不需要回到起点重算。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-46\">四十六 · 资源分配的判定式：alloc 与 SLO 可行性</h3>\n<p>拆池之后的核心问题不再是“批多大”，而是“每个池分多少 SM 与显存”。本条目给出的分配式是带尾延迟约束的利用率最大化：</p>\n<div class=\"formula\">$$\\text{alloc}_j = \\arg\\max \\sum_j U_j \\;\\text{s.t.}\\; L_j \\le \\text{SLO}_j$$</div>\n<p>其中 $U_j$ 为第 $j$ 个池的 GPU 利用率，$L_j$ 为该池尾延迟，$\\text{SLO}_j$ 为对应阶段的服务目标。这个式子的工程含义是：它不是无约束的负载均衡，而是把 SLO 当作硬边界、把利用率当作目标函数。当某个池的 $L_j$ 逼近 $\\text{SLO}_j$ 时，可行域收缩，目标函数被迫让位——这正是抢占触发点。</p>\n<p>对照来看，统一批处理方案没有 $j$ 这个下标，约束退化为单条端到端尾延迟，于是优化空间被压成一维：只能调总批大小。这就是它在混合模态下 util 上不去的数学原因——一维变量无法同时满足三条形状不同的延迟曲线。而 MTP 方案把并行度藏进模型内部，$j$ 退化为“草稿步数”，约束仍是单池的，但代价转移到模型显存和接受率上。</p>\n<p>可行性判定还要加一条隐含约束：跨池迁移的带宽预算。设每请求每 token 需迁移的 KV 字节为 $b$，池间有效带宽为 $B$，则流水线不出现气泡的必要条件是单位时间内产生的 KV 字节量不超过 $B$ 扣除同步开销后的余量。这一条不写进 alloc 式，但它是 alloc 解是否可执行的先决条件——带宽不够时，alloc 算得再优，流水线也会退化成串行。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-47\">四十七 · 抢占语义的选型：软抢占、冷却窗口与饥饿</h3>\n<p>抢占是拆池方案里最容易配错的一环。同族算法中，无抢占方案（统一批处理、分块编解码器）把公平性交给 FIFO，代价是长预填请求可以无限期阻塞后续解码迭代；硬抢占方案（立即驱逐、立即重排）能压住尾延迟，但会在 SLO 边界反复震荡——一个请求刚被驱逐又立刻被重排回来，形成抖动。本条目取的是中间态：软抢占 + 最小驻留时间 + 重排冷却窗口。</p>\n<p>机制上，SLO 监控在每次迭代结束时比较各池的尾延迟估计与 $\\text{SLO}_j$，超限请求获得 SM 与带宽的优先权，但被驱逐的请求在最小驻留时间内不得再次被驱逐，重排动作在冷却窗口内不得对同一请求重复触发。伪代码思路是：</p>\n<ul>\n<li>每轮迭代：采样各池尾延迟 → 若 $L_j &gt; \\text{SLO}_j$ 则标记该池进入抢占态；</li>\n<li>从低优先级池选victim，检查其驻留时间是否超过最小值，未超过则跳过；</li>\n<li>重排目标请求前检查冷却窗口，窗口内则排队等待而非立即插入；</li>\n<li>抢占后重新求解 alloc，若可行域仍为空则降级为串行移交。</li>\n</ul>\n<p>这套语义的代价是可预测性换稳定性：软抢占让尾延迟不会瞬间达标，而是以冷却窗口为时间常数收敛。选型判据是——若业务 SLO 是硬实时（如全双工对话的往返约束），软抢占的收敛时间可能不够，此时应优先考虑单池 MTP 方案把并行度收进模型内部，避免跨池抢占的不确定性；若 SLO 是统计性的（$\\Pr(L_{\\text{first}} \\le L^{\\star}) \\ge 1-\\epsilon$），软抢占的收敛特性恰好匹配这种概率约束。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-48\">四十八 · 耦合方式对照：流水线、串行与模型内并行</h3>\n<p>三种耦合方式的差别不在“谁更快”，而在“代价落在哪个资源上”。串行移交（预填完成 → 解码 → 声码器）的代价是端到端延迟等于三段之和，但跨池状态迁移只在阶段边界发生一次，显存拷贝量最小；流水线并行把声码器池与解码池重叠，端到端延迟压到最长段加流水线深度，代价是帧块到达节奏必须与解码 token 产出匹配——不匹配时声码器池空转或积压，这正是本条目列出的失败模式之一；模型内多 token 预测把并行度收进单次前向，代价是模型显存增加和接受率不足时的无效计算。</p>\n<p>选型的量化判据是“阶段时长比”。若声码器段时长占端到端比例很小，流水线收益有限而同步开销照付，此时串行移交更划算；若声码器段与解码段时长相当，流水线的重叠收益最大，但必须配套帧块节奏控制——按解码池的 token 产出速率反推声码器池的帧块批大小，而不是让声码器池按固定帧率自顾自批处理。后者正是空转/积压的根源。</p>\n<p>一个具体例子：语音+文本混合流中，文本请求的预填短、解码长，语音请求的预填含音频条件编码、解码短但声码器段固定。若两者共用单池，文本的长解码会持续占用 SM，语音请求的声码器段被迫排队，尾延迟在语音侧先破 SLO。拆池后，文本解码池与语音声码器池各自按特征批处理，语音侧的固定帧率特性使其批大小可静态确定，文本侧则按 token 预算动态增删——两类请求的 SLO 由不同的池分别兜住，而不是靠一个批大小同时讨好两边。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-49\">四十九 · 规模上限与退选条件</h3>\n<p>拆池方案不是无条件扩展的。规模上限受两条硬约束夹住：跨池带宽与显存容量。池数增加时，KV 与状态的迁移路径数按池间组合增长，同步开销随之上升；当池间带宽不足，流水线气泡出现，GPU 利用率反而下降——这是拆池方案唯一会“越优化越差”的区间。判定这条线的方法是在 profiling 中测量单位时间跨池迁移字节量与池间有效带宽的比值，比值逼近 1 时即到达退选点。</p>\n<p>退选路径有两条。第一条是退回统一连续批处理：当各阶段计算特征差异缩小（例如量化后预填与解码都变成 memory-bound），拆池的收益被迁移开销吃掉，单池反而更稳。第二条是退回 MTP 单池方案：当跨池带宽成为硬瓶颈且模型具备多 token 头时，把并行度从“池间”搬到“模型内”，用模型显存换掉跨池同步，代价位从带宽转到显存。两条退选路径的共同点是——它们都把 $j$ 这个下标消掉，把多维约束压回一维，用确定性换掉解耦带来的调度复杂度。</p>\n<p>工程判断的落点是：先测阶段时长比与跨池带宽比这两个数，再查决策表。时长比接近 1 且带宽比远小于 1，选本条目；时长比悬殊或带宽比逼近 1，选单池方案；有 MTP 头且不想承担跨池同步，选模型内并行。这三个数不需要上线就能从一次 profiling 得到，选型因此是可复现的工程动作而非经验判断。</p>\n\n<h3 id=\"alg-streamwise-multimodal-sched-sec-50\">五十 · 阶段解耦调度的边界：何时该换回单池连续批处理</h3>\n<p>本方案与统一批调度（单池连续批处理）的分野不在算法复杂度，而在“阶段计算特征是否真的不可调和”。预填是计算密集的大矩阵乘，解码是访存密集的逐 token 迭代，声码器是帧块并行的波形合成，三者的最优批形状、SM 占用与显存足迹互不相容。当模态单一、阶段间特征接近时，拆池带来的跨池 KV cache 与状态迁移开销会超过收益：每次移交都要把 KV 从预填池显存拷到解码池可见的地址，并做流同步，池间带宽不足时流水线出现气泡，GPU 利用率反而下降。判据可写成带迁移代价的资源分配式：</p>\n<div class=\"formula\">$$\\text{alloc}_j=\\arg\\max\\sum_j U_j \\;\\text{s.t.}\\; L_j\\le \\text{SLO}_j,\\quad U_j^{\\text{eff}}=U_j-\\frac{C_{\\text{mig},j}}{T_j}$$</div>\n<p>其中 $C_{\\text{mig},j}$ 是第 $j$ 池单位时间内的迁移与同步开销，$T_j$ 为其调度周期。当 $C_{\\text{mig}}$ 与池内计算时间同量级，拆池的净利用率增益被吃掉，此时单池连续批处理更稳。另一条失效路径在抢占侧：解码池按 token 预算动态增删请求，若最小驻留时间与重排冷却窗口配置不当，尾延迟超限请求反复抢占，解码池饥饿或抖动，尾延迟在 SLO 边界震荡，$\\Pr(L_{\\text{first}}\\le L^{\\star})$ 反而下降。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>选阶段解耦池</th><th>选单池连续批处理</th></tr></thead><tbody><tr><td>阶段计算特征差异</td><td>预填/解码/声码器差异大</td><td>差异小或仅单模态</td></tr><tr><td>跨池带宽与显存余量</td><td>充裕，迁移开销可摊薄</td><td>紧张，拷贝同步成瓶颈</td></tr><tr><td>尾延迟约束</td><td>各阶段 SLO 独立且严格</td><td>端到端宽松、可容忍排队</td></tr><tr><td>帧块到达节奏</td><td>与解码 token 产出匹配</td><td>不匹配，声码器池空转或积压</td></tr></tbody></table>\n<p>与 FlashTTS 一类单模型内多 token 预测的流式方案对照：后者把并行度压在模型内部，不引入跨池状态迁移，适合模型与声码器紧耦合、阶段边界模糊的场景；本方案以跨模态阶段拆分为核心，收益来自各池按自身特征批处理，代价是调度器要同时维护三套队列、抢占策略与迁移路径。工程判断落在规模上限上：上限由跨池带宽与显存容量共同约束，扩容时优先加宽池间链路而非加卡，否则迁移开销随池数线性上升而利用率不增。声码器池与解码池流水并行时，帧块到达节奏必须与 token 产出对齐，否则声码器池空转或积压，此时应退回把声码器并入解码池尾部的串行形态。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2026 · 批调度与实时率 SLO</td></tr><tr><td>解决什么</td><td>多模态生成服务（语音+文本+视频）中不同阶段计算特征差异大，统一批调度导致 GPU 利用率低、尾延迟高，难以满足实时 …</td></tr><tr><td>一句话机制</td><td>按阶段（预填、自回归解码、声码器/解码器）拆分资源池，以 token/帧块为调度单位做连续批处理与抢占，按 SLO 分…</td></tr><tr><td>代价与失效</td><td>跨池 KV cache 与状态迁移增加显存拷贝与同步开销；抢占与重排策略复杂，配置不当会导致解码池饥饿或抖动</td></tr><tr><td>后继</td><td>流式多模态批调度</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-streamwise-multimodal-sched · 共 8 个片段</p>\n";break;}}})();
